    VERSION,
    STORAGE_KEY,
    MAX_AGE_MS,
    ACTIONS,
    safeReturnTarget,
    sanitizeDiscovery,
    sanitizeProfile,
    load,
    capture,
    consumeAction,
    clearDogDraft,
    adoptLegacyDogDraft,
