// ---- trail-route-refs.js ----
(function (global) {
  'use strict';

  const REF_PATTERN = /\b(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?\b/gi;
  const ROUTE_WORD_PATTERN = /\b(?:trails?|paths?|routes?|sentieri)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?(?:\s*(?:,\s*(?:and\s+)?|\/\s*|&\s*|→\s*|(?:and|then|to|onto)\s+)(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)*)/gi;
  const NAMED_SENTIERO_PATTERN = /\bsentiero\s+(?:[A-ZÀ-ÖØ-öø-ÿ'’-]+\s+){0,3}((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\b/gi;

  function normaliseRef(value) {
    const ref = String(value == null ? '' : value)
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '');
    return /^(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?$/.test(ref) ? ref : null;
  }

  function refsFromText(text) {
    const refs = [];
    const source = String(text == null ? '' : text);
    for (const match of source.matchAll(ROUTE_WORD_PATTERN)) {
      const candidates = match[1].match(REF_PATTERN) || [];
      candidates.forEach(candidate => {
        const ref = normaliseRef(candidate);
        if (ref && !refs.includes(ref)) refs.push(ref);
      });
    }
    for (const match of source.matchAll(NAMED_SENTIERO_PATTERN)) {
      const ref = normaliseRef(match[1]);
      if (ref && !refs.includes(ref)) refs.push(ref);
    }
    return refs;
  }

  function explicitRefs(trail) {
    const values = [];
    ['routeRefs', 'routeNumbers', 'trailRefs', 'trailNumbers'].forEach(key => {
      const field = trail && trail[key];
      if (Array.isArray(field)) values.push(...field);
      else if (field != null) values.push(field);
    });
    if (trail && trail.ref != null) values.push(trail.ref);
    (Array.isArray(trail && trail.routeRefSegments) ? trail.routeRefSegments : [])
      .forEach(segment => values.push(segment && segment.ref));
    return values.map(value => normaliseRef(
      value && typeof value === 'object'
        ? value.ref || value.number || value.label
        : value
    )).filter(Boolean);
  }

  function switchRefs(instruction) {
    const match = String(instruction == null ? '' : instruction).match(
      /\bswitch\s+from\s+(?:trail|path|route|sentiero)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\s+onto\s+(?:trail|path|route|sentiero)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\b/i
    );
    if (!match) return null;
    const from = normaliseRef(match[1]);
    const to = normaliseRef(match[2]);
    return from && to ? { from, to } : null;
  }

  function nearestPathIndex(path, point, startIndex) {
    if (!point || !Number.isFinite(Number(point.lat)) || !Number.isFinite(Number(point.lng))) return -1;
    let bestIndex = -1;
    let bestDistance = Infinity;
    for (let index = Math.max(0, startIndex || 0); index < path.length; index += 1) {
      const candidate = path[index];
      if (!Array.isArray(candidate) || candidate.length < 2) continue;
      const dLat = Number(candidate[0]) - Number(point.lat);
      const dLng = Number(candidate[1]) - Number(point.lng);
      const distance = dLat * dLat + dLng * dLng;
      if (distance < bestDistance) {
        bestDistance = distance;
        bestIndex = index;
      }
    }
    return bestIndex;
  }

  function switchesForTrail(trail) {
    return (Array.isArray(trail && trail.decisionPoints) ? trail.decisionPoints : [])
      .map(point => ({ point, refs: switchRefs(point && point.instruction) }))
      .filter(item => item.refs && Number.isFinite(Number(item.point && item.point.lat))
        && Number.isFinite(Number(item.point && item.point.lng)))
      .map(item => ({
        from:item.refs.from,
        to:item.refs.to,
        km:Number.isFinite(Number(item.point.km)) ? Number(item.point.km) : null,
        lat:Number(item.point.lat),
        lng:Number(item.point.lng),
        instruction:String(item.point.instruction || ''),
      }));
  }

  function segmentsForTrail(trail) {
    if (!trail || !Array.isArray(trail.path) || trail.path.length < 2) return [];
    const verified = (Array.isArray(trail.routeRefSegments) ? trail.routeRefSegments : [])
      .map(segment => ({
        ref: normaliseRef(segment && segment.ref),
        path: segment && segment.path,
        source: segment && segment.source,
      }))
      .filter(segment => segment.ref && Array.isArray(segment.path) && segment.path.length > 1);
    if (verified.length) return verified;

    const switches = switchesForTrail(trail);
    if (!switches.length) return [];

    const segments = [];
    let currentRef = switches[0].from;
    let startIndex = 0;
    switches.forEach(item => {
      const endIndex = nearestPathIndex(trail.path, item, startIndex);
      if (endIndex > startIndex) {
        segments.push({ ref: currentRef, path: trail.path.slice(startIndex, endIndex + 1) });
        startIndex = endIndex;
      }
      currentRef = item.to;
    });
    if (startIndex < trail.path.length - 1) {
      segments.push({ ref: currentRef, path: trail.path.slice(startIndex) });
    }
    return segments.filter(segment => segment.path.length > 1);
  }

  function forTrail(trail) {
    if (!trail || typeof trail !== 'object') return [];
    const refs = [];
    const add = value => {
      const ref = normaliseRef(value);
      if (ref && !refs.includes(ref)) refs.push(ref);
    };

    explicitRefs(trail).forEach(add);
    refsFromText(trail.routeSource && trail.routeSource.name).forEach(add);
    (Array.isArray(trail.decisionPoints) ? trail.decisionPoints : [])
      .forEach(point => refsFromText(point && point.instruction).forEach(add));
    return refs.slice(0, 8);
  }

  const SHIELD_IMAGE_ID = 'orma-route-number-shield';

  function featuresForTrail(trail) {
    const sections = segmentsForTrail(trail);
    const refs = forTrail(trail);
    // Verified section geometry remains the first choice. When a route has a
    // known sequence of references but no surveyed switch coordinates, keep
    // the sequence together on the full ORMA line. This makes the numbers
    // visible without pretending that an unverified point is the junction.
    const labelledPaths = sections.length
      ? sections
      : (refs.length && Array.isArray(trail && trail.path)
        ? [{ ref:refs.join(' / '), path:trail.path }]
        : []);
    return labelledPaths
      .filter(section => section.ref && Array.isArray(section.path) && section.path.length > 1)
      .map(section => ({
        type:'Feature',
        properties:{ id:trail.id, routeRef:section.ref },
        geometry:{ type:'LineString', coordinates:section.path.map(([lat, lng]) => [lng, lat]) },
      }));
  }

  function registerShieldImage(map) {
    if(map.hasImage(SHIELD_IMAGE_ID)) return;
    const canvas = document.createElement('canvas');
    canvas.width = 104;
    canvas.height = 68;
    const context = canvas.getContext('2d');
    context.fillStyle = '#FFFFFF';
    context.fillRect(2, 2, 100, 64);
    context.strokeStyle = '#17221B';
    context.lineWidth = 5;
    context.strokeRect(4.5, 4.5, 95, 59);
    map.addImage(
      SHIELD_IMAGE_ID,
      context.getImageData(0, 0, 104, 68),
      { pixelRatio:2, stretchX:[[20, 84]], stretchY:[[16, 52]], content:[14, 9, 90, 59] }
    );
  }

  function addShieldLayer(map, options) {
    const config = options || {};
    if(!config.id || !config.source || map.getLayer(config.id)) return;
    registerShieldImage(map);
    map.addLayer({
      id:config.id,
      type:'symbol',
      source:config.source,
      minzoom:8,
      layout:{
        'symbol-placement':'line',
        'symbol-spacing':['interpolate', ['linear'], ['zoom'], 8, 125, 12, 155, 16, 190, 19, 230],
        'icon-image':SHIELD_IMAGE_ID,
        'icon-text-fit':'both',
        'icon-text-fit-padding':[6, 10, 6, 10],
        'icon-size':['interpolate', ['linear'], ['zoom'], 8, 1.08, 12, 1.16, 16, 1.26, 19, 1.34],
        'icon-rotation-alignment':'viewport',
        'icon-allow-overlap':true,
        'icon-ignore-placement':true,
        'text-field':['get', 'routeRef'],
        'text-font':['Open Sans Bold', 'Arial Unicode MS Bold'],
        'text-size':['interpolate', ['linear'], ['zoom'], 8, 16, 12, 18, 16, 21, 19, 23],
        'text-rotation-alignment':'viewport',
        'text-keep-upright':true,
        'text-allow-overlap':true,
        'text-ignore-placement':true,
      },
      paint:{
        'text-color':'#17221B',
        'text-halo-color':'#FFFFFF',
        'text-halo-width':1.2,
      },
    }, config.beforeId);
  }

  const api = {
    forTrail,
    refsFromText,
    normaliseRef,
    segmentsForTrail,
    switchesForTrail,
    featuresForTrail,
    registerShieldImage,
    addShieldLayer,
    SHIELD_IMAGE_ID,
  };
  global.DoloPawsTrailRouteRefs = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof window !== 'undefined' ? window : globalThis);
;

// ---- trail.js ----
function safetyLabel(level){
  if(level === 'low-risk') return t('safety.low');
  if(level === 'moderate') return t('safety.moderate');
  return t('safety.caution');
}
function trailSafetyLabel(trail){
  const base = safetyLabel(trail.safetyLevel);
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.riskLabel(trail, base) : base;
}
function safetyColor(level){
  if(level === 'low-risk') return '#2C5C34';
  if(level === 'moderate') return '#8A5A16';
  return '#9C3A25';
}

// The logged-in homepage colours routes by the dog's match score. Reuse its
// exact thresholds here so opening a trail never changes the map's meaning.
function detailRouteColorForScore(score){
  return score >= 85 ? '#4A7856' : score >= 65 ? '#C98A2E' : '#9C3A25';
}
function applyDetailRouteColor(color){
  window._dolopawsTrailRouteColor = color;
  const map = window._dolopawsTrailMap;
  if(!map || !map.isStyleLoaded || !map.isStyleLoaded()) return;
  if(map.getLayer('single-trail-path-line')) map.setPaintProperty('single-trail-path-line', 'line-color', color);
  if(map.getLayer('single-trail-direction-arrows')) map.setPaintProperty('single-trail-direction-arrows', 'text-halo-color', color);
}

function safetyClass(level){
  if(level === 'low-risk') return 'safety-low';
  if(level === 'moderate') return 'safety-moderate';
  return 'safety-caution';
}
function trailProductBadge(type, label){
  if(window.DoloPawsIcons) return window.DoloPawsIcons.badgeHtml(type, label);
  return `<span class="dp-badge dp-badge--${type}"><span>${label}</span></span>`;
}
function trailProductIcon(type, size = 16){
  return window.DoloPawsIcons ? window.DoloPawsIcons.renderIconSvg(type, { mode:'inline', color:'currentColor', size }) : '';
}
function withoutLeadingSymbol(label){
  return String(label || '').replace(/^[^\p{L}\p{N}]+/u, '');
}
function trustedWaterLabel(trail, label){
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.waterPointLabel(trail, label) : label;
}
function trustedStartLabel(trail, label){
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.startPointLabel(trail, label) : label;
}

function renderTrailDetailContent(t){
  const rifugi = Array.isArray(t.rifugi) ? t.rifugi : [];
  const water = Array.isArray(t.waterSources) ? t.waterSources : [];

  const rifugiHtml = rifugi.length > 0
    ? `<ul style="margin:0 0 14px;padding-left:18px;">${rifugi.map(r => `<li>Km ${r.km} — ${r.name}</li>`).join('')}</ul>`
    : `<p style="margin:0 0 14px;">${window.t('trail.noRifugi')}</p>`;

  const waterHtml = water.length > 0
    ? `<ul style="margin:0 0 8px;padding-left:18px;">${water.map(w => `<li>Km ${w.km} — ${trustedWaterLabel(t, w.label)}</li>`).join('')}</ul>` +
      (t.curated === false ? '<p style="margin:0 0 14px;font-size:12px;color:var(--ink-soft);">Availability can change. Carry a backup supply.</p>' : '')
    : `<p style="margin:0 0 14px;">${window.t('trail.noWater')}</p>`;

  return `
    <div style="margin-bottom:14px;">
      <div class="dp-inline-status" style="font-weight:700;color:var(--ink);margin-bottom:4px;">${trailProductIcon('hut')}<span>${withoutLeadingSymbol(window.t('trail.rifugiHead'))}</span></div>
      ${rifugiHtml}
    </div>
    <div style="margin-bottom:14px;">
      <div class="dp-inline-status" style="font-weight:700;color:var(--ink);margin-bottom:4px;">${trailProductIcon('water')}<span>${withoutLeadingSymbol(window.t('trail.waterHead'))}</span></div>
      ${waterHtml}
    </div>
  `;
}

function distMeters(a, b){
  return Math.hypot(a[0]-b[0], a[1]-b[1]) * 111000;
}

function mapDistanceKm(a, b){
  const rad = Math.PI / 180;
  const dLat = (b[0] - a[0]) * rad;
  const dLng = (b[1] - a[1]) * rad;
  const lat1 = a[0] * rad;
  const lat2 = b[0] * rad;
  const h = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
}

function formatApproachDistance(distanceKm){
  if(!Number.isFinite(distanceKm)) return '';
  if(distanceKm < 1) return `${Math.max(10, Math.round(distanceKm * 1000 / 10) * 10)} m`;
  return `${distanceKm.toFixed(distanceKm < 10 ? 1 : 0)} km`;
}

function initLoopComposer(map, t){
  const openButton = document.getElementById('mapLoopComposerBtn');
  const panel = document.getElementById('mapLoopComposerPanel');
  const dismissButton = document.getElementById('mapLoopDismissBtn');
  const addCentreButton = document.getElementById('mapLoopAddCentreBtn');
  const undoButton = document.getElementById('mapLoopUndoBtn');
  const closeButton = document.getElementById('mapLoopCloseBtn');
  const saveButton = document.getElementById('mapLoopSaveBtn');
  const status = document.getElementById('mapLoopStatus');
  const distance = document.getElementById('mapLoopDistance');
  const pointCount = document.getElementById('mapLoopPointCount');
  const pointList = document.getElementById('mapLoopPointList');
  const mapBox = document.getElementById('trailMapBox');
  const coverage = window.DoloPawsTrailRoutingCoverage;
  const coverageEntry = coverage && coverage.trails ? coverage.trails[t.id] : null;
  const router = window.DoloPawsFootpathRouter;
  if(!openButton || !panel || !dismissButton || !addCentreButton || !undoButton ||
     !closeButton || !saveButton || !status || !distance || !pointCount || !pointList ||
     !coverageEntry || !coverageEntry.graphUrl || !router ||
     typeof router.routeThroughPoints !== 'function' || typeof router.routeLoop !== 'function') return;

  const MAX_POINTS = 3;
  const MAX_LEG_DISTANCE_M = 5000;
  const MAX_TOTAL_DISTANCE_M = Number.isFinite(coverage.maxWalkingRouteM)
    ? coverage.maxWalkingRouteM * 2
    : 10000;
  const STORAGE_KEY = 'orma-custom-loops-v1';
  let active = false;
  let busy = false;
  let closed = false;
  let points = [];
  let preview = null;
  let graphPromise = null;
  let calculationVersion = 0;
  let markers = [];
  openButton.hidden = false;

  function loadGraph(){
    if(!graphPromise){
      graphPromise = fetch(coverageEntry.graphUrl, { credentials:'same-origin' })
        .then(response => {
          if(!response.ok) throw new Error(`routing-graph-${response.status}`);
          return response.json();
        })
        .then(graph => router.validateGraph(graph) ? graph : null)
        .catch(() => null);
    }
    return graphPromise;
  }

  function markerElement(index){
    const element = document.createElement('span');
    element.className = `map-access-marker ${index === 0 ? 'map-access-marker--you' : 'map-access-marker--target'}`;
    element.textContent = index === 0 ? '' : String(index);
    element.setAttribute('aria-hidden', 'true');
    return element;
  }

  function drawMarkers(){
    markers.forEach(marker => marker.remove());
    markers = points.map((point, index) => new maplibregl.Marker({ element:markerElement(index) })
      .setLngLat([point.lng, point.lat])
      .addTo(map));
  }

  function emptyRoute(){
    return { type:'FeatureCollection', features:[] };
  }

  function drawRoute(path){
    const data = Array.isArray(path) && path.length > 1 ? {
      type:'Feature',
      properties:{ mode:closed ? 'mapped-loop' : 'mapped-waypoints' },
      geometry:{ type:'LineString', coordinates:path.map(point => [point.lng, point.lat]) },
    } : emptyRoute();
    if(!map.isStyleLoaded()){
      map.once('load', () => drawRoute(path));
      return;
    }
    const source = map.getSource('trail-loop-route');
    if(source){
      source.setData(data);
      return;
    }
    map.addSource('trail-loop-route', { type:'geojson', data });
    map.addLayer({
      id:'trail-loop-route-casing',
      type:'line',
      source:'trail-loop-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#ffffff', 'line-width':10, 'line-opacity':0.92 },
    });
    map.addLayer({
      id:'trail-loop-route-line',
      type:'line',
      source:'trail-loop-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#2E684F', 'line-width':6, 'line-opacity':0.98 },
    });
  }

  function pointLabel(index){
    return index === 0 ? 'Start' : `Point ${index + 1}`;
  }

  function renderPointList(){
    pointList.replaceChildren();
    points.forEach((point, index) => {
      const item = document.createElement('li');
      item.className = 'map-loop-point';
      item.append(document.createTextNode(pointLabel(index)));
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.textContent = '×';
      remove.disabled = busy;
      remove.setAttribute('aria-label', `Remove ${pointLabel(index).toLowerCase()}`);
      remove.addEventListener('click', () => removePoint(index));
      item.append(remove);
      pointList.append(item);
    });
  }

  function render(){
    panel.hidden = !active;
    openButton.setAttribute('aria-pressed', String(active));
    if(mapBox) mapBox.classList.toggle('loop-composer-active', active);
    panel.dataset.state = closed ? 'closed' : 'open';
    distance.textContent = preview ? formatApproachDistance(preview.distanceM / 1000) : '—';
    pointCount.textContent = `${points.length} / ${MAX_POINTS}`;
    addCentreButton.disabled = busy || closed || points.length >= MAX_POINTS;
    undoButton.disabled = busy || !points.length;
    closeButton.hidden = closed;
    closeButton.disabled = busy || points.length < MAX_POINTS || !preview;
    saveButton.hidden = !closed;
    saveButton.disabled = busy || !closed || !preview;
    renderPointList();
  }

  function fitPreview(){
    if(!preview || !Array.isArray(preview.path) || !preview.path.length || !window.maplibregl) return;
    const bounds = new maplibregl.LngLatBounds();
    preview.path.forEach(point => bounds.extend([point.lng, point.lat]));
    map.fitBounds(bounds, { padding:{ top:70, right:50, bottom:190, left:50 }, maxZoom:16, duration:500 });
  }

  async function recalculate(closeRequested){
    const version = ++calculationVersion;
    if(points.length < 2){
      preview = null;
      closed = false;
      drawRoute([]);
      status.textContent = points.length ? 'Tap the map to add a must-pass point.' : 'Tap the map to choose your start.';
      render();
      return;
    }
    busy = true;
    status.textContent = closeRequested ? 'Closing the loop on mapped walking paths…' : 'Connecting the selected points…';
    render();
    const graph = await loadGraph();
    if(version !== calculationVersion) return;
    const options = {
      maxPoints:MAX_POINTS,
      maxLegDistanceM:MAX_LEG_DISTANCE_M,
      maxTotalDistanceM:MAX_TOTAL_DISTANCE_M,
      maxSnapDistanceM:90,
      maxTargetSnapDistanceM:90,
    };
    const result = graph
      ? (closeRequested ? router.routeLoop(points, graph, options) : router.routeThroughPoints(points, graph, options))
      : null;
    busy = false;
    if(!result){
      preview = null;
      closed = false;
      drawRoute([]);
      status.textContent = graph
        ? 'These points cannot form a bounded mapped route. Remove a point and choose a closer path.'
        : 'ORMA’s walking graph is unavailable here right now. Your points have been kept.';
      render();
      return;
    }
    preview = result;
    closed = closeRequested;
    drawRoute(preview.path);
    status.textContent = closed
      ? 'Loop ready. Review mapped access, signs, and current conditions before saving.'
      : points.length < MAX_POINTS
        ? 'Mapped preview ready. Add another must-pass point.'
        : 'Mapped preview ready. Close the loop when the shape looks right.';
    render();
    if(closed) fitPreview();
  }

  function addPoint(point){
    if(!active || busy || closed || points.length >= MAX_POINTS ||
       !point || !Number.isFinite(point.lat) || !Number.isFinite(point.lng)) return;
    points.push({ lat:point.lat, lng:point.lng });
    drawMarkers();
    recalculate(false);
  }

  function removePoint(index){
    if(busy || index < 0 || index >= points.length) return;
    calculationVersion += 1;
    points.splice(index, 1);
    closed = false;
    preview = null;
    saveButton.textContent = 'Save loop';
    drawMarkers();
    recalculate(false);
  }

  function reset(){
    calculationVersion += 1;
    busy = false;
    closed = false;
    points = [];
    preview = null;
    markers.forEach(marker => marker.remove());
    markers = [];
    drawRoute([]);
    status.textContent = 'Tap the map to choose your start.';
    saveButton.textContent = 'Save loop';
    render();
  }

  function open(){
    active = true;
    reset();
    render();
  }

  function dismiss(){
    active = false;
    reset();
    render();
    openButton.focus();
  }

  function save(){
    if(!closed || !preview) return;
    const record = {
      id:`loop-${Date.now()}`,
      sourceTrailId:t.id,
      createdAt:new Date().toISOString(),
      graphUrl:coverageEntry.graphUrl,
      source:preview.source,
      distanceM:Math.round(preview.distanceM),
      points:points.map(point => ({ lat:point.lat, lng:point.lng })),
      path:preview.path.map(point => [point.lat, point.lng]),
    };
    try{
      const existing = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const records = Array.isArray(existing) ? existing : [];
      localStorage.setItem(STORAGE_KEY, JSON.stringify([record, ...records].slice(0, 20)));
      saveButton.textContent = 'Saved';
      saveButton.disabled = true;
      status.textContent = 'Loop saved on this device. Review local signs and conditions before walking.';
    }catch(error){
      status.textContent = 'This browser could not save the loop. The mapped preview is still available.';
    }
  }

  openButton.addEventListener('click', () => active ? dismiss() : open());
  dismissButton.addEventListener('click', dismiss);
  addCentreButton.addEventListener('click', () => {
    const centre = map.getCenter();
    addPoint({ lat:centre.lat, lng:centre.lng });
  });
  undoButton.addEventListener('click', () => {
    if(closed){
      closed = false;
      preview = null;
      saveButton.textContent = 'Save loop';
      recalculate(false);
      return;
    }
    removePoint(points.length - 1);
  });
  closeButton.addEventListener('click', () => recalculate(true));
  saveButton.addEventListener('click', save);
  map.on('click', event => {
    if(active) addPoint({ lat:event.lngLat.lat, lng:event.lngLat.lng });
  });
  document.addEventListener('keydown', event => {
    if(event.key === 'Escape' && active) dismiss();
  });
  render();
}

function initNearestTrailDirections(map, t){
  const button = document.getElementById('mapNearestDirectionsBtn');
  const panel = document.getElementById('mapNearestDirectionsPanel');
  const status = document.getElementById('mapNearestDirectionsStatus');
  const stepsWrap = document.getElementById('mapNearestDirectionsStepsWrap');
  const stepsList = document.getElementById('mapNearestDirectionsSteps');
  if(!button || !panel || !status || !Array.isArray(t.path) || !t.path.length ||
     !window.DoloPawsTrailAccess || !window.DoloPawsFootpathRouter) return;

  const defaultLabel = 'Get directions to trail';
  const coverage = window.DoloPawsTrailRoutingCoverage;
  const coverageEntry = coverage && coverage.trails ? coverage.trails[t.id] : null;
  const coverageEntries = coverage && coverage.trails
    ? Object.values(coverage.trails).filter(entry => entry && entry.graphUrl && entry.bounds)
    : [];
  let activePlan = null;
  const graphPromises = new Map();
  let originMarker = null;
  let targetMarker = null;
  button.hidden = false;

  function setButtonLabel(label){
    const labelNode = button.querySelector('span');
    if(labelNode) labelNode.textContent = label;
  }

  function markerElement(type){
    const element = document.createElement('span');
    element.className = `map-access-marker map-access-marker--${type}`;
    element.setAttribute('aria-hidden', 'true');
    return element;
  }

  function setPanelMessage(message){
    panel.hidden = !message;
    status.textContent = message || '';
  }

  function clearSteps(){
    if(stepsWrap) stepsWrap.hidden = true;
    if(stepsList) stepsList.replaceChildren();
  }

  function renderSteps(instructions){
    clearSteps();
    if(!stepsWrap || !stepsList || !Array.isArray(instructions) || !instructions.length) return;
    instructions.slice(0, 12).forEach(step => {
      const item = document.createElement('li');
      const distance = step.distanceM > 0
        ? ` for ${formatApproachDistance(step.distanceM / 1000)}`
        : '';
      item.textContent = `${step.action}${distance}`;
      stepsList.appendChild(item);
    });
    stepsWrap.hidden = false;
  }

  function loadRoutingGraph(entry){
    const selectedEntry = entry || coverageEntry;
    if(!selectedEntry || !selectedEntry.graphUrl) return Promise.resolve(null);
    if(!graphPromises.has(selectedEntry.graphUrl)){
      graphPromises.set(selectedEntry.graphUrl, fetch(selectedEntry.graphUrl, { credentials:'same-origin' })
        .then(response => {
          if(!response.ok) throw new Error(`routing-graph-${response.status}`);
          return response.json();
        })
        .then(graph => window.DoloPawsFootpathRouter.validateGraph(graph) ? graph : null)
        .catch(() => null));
    }
    return graphPromises.get(selectedEntry.graphUrl);
  }

  function boundsContainPoint(bounds, point){
    return bounds && point &&
      point.lat >= bounds.south && point.lat <= bounds.north &&
      point.lng >= bounds.west && point.lng <= bounds.east;
  }

  function routingEntriesForPoint(point, origin){
    const candidates = coverageEntries
      .filter(entry => boundsContainPoint(entry.bounds, point) && boundsContainPoint(entry.bounds, origin))
      .sort((first, second) => {
        if(first === coverageEntry) return -1;
        if(second === coverageEntry) return 1;
        const firstArea = (first.bounds.north - first.bounds.south) * (first.bounds.east - first.bounds.west);
        const secondArea = (second.bounds.north - second.bounds.south) * (second.bounds.east - second.bounds.west);
        return firstArea - secondArea;
      });
    return candidates.filter((entry, index) =>
      candidates.findIndex(candidate => candidate.graphUrl === entry.graphUrl) === index);
  }

  function removeMappedRoute(){
    if(!map.isStyleLoaded() || !map.getSource('trail-access-route')) return;
    map.getSource('trail-access-route').setData({ type:'FeatureCollection', features:[] });
  }

  function drawMappedRoute(path){
    if(!map.isStyleLoaded() || !Array.isArray(path) || path.length < 2) return;
    const data = {
      type:'Feature',
      properties:{ mode:'mapped-footpath' },
      geometry:{ type:'LineString', coordinates:path.map(point => [point.lng, point.lat]) },
    };
    const source = map.getSource('trail-access-route');
    if(source){
      source.setData(data);
      return;
    }
    map.addSource('trail-access-route', { type:'geojson', data });
    map.addLayer({
      id:'trail-access-route-casing',
      type:'line',
      source:'trail-access-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#ffffff', 'line-width':8, 'line-opacity':0.92 },
    });
    map.addLayer({
      id:'trail-access-route-line',
      type:'line',
      source:'trail-access-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#3E7A91', 'line-width':5, 'line-opacity':0.96 },
    });
  }

  function showPlan(plan, mapped){
    if(originMarker) originMarker.remove();
    originMarker = new maplibregl.Marker({ element:markerElement('you') })
      .setLngLat([plan.origin.lng, plan.origin.lat])
      .addTo(map);
    const bounds = new maplibregl.LngLatBounds();
    bounds.extend([plan.origin.lng, plan.origin.lat]);
    if(mapped && Array.isArray(plan.path)){
      drawMappedRoute(plan.path);
      plan.path.forEach(point => bounds.extend([point.lng, point.lat]));
    } else {
      removeMappedRoute();
      bounds.extend([plan.target.lng, plan.target.lat]);
    }
    if(targetMarker) targetMarker.remove();
    if(plan.mode === 'mapped-point' || plan.mode === 'external-point'){
      targetMarker = new maplibregl.Marker({ element:markerElement('target') })
        .setLngLat([plan.target.lng, plan.target.lat])
        .addTo(map);
    }
    map.fitBounds(bounds, { padding:70, maxZoom:16, duration:700 });
  }

  async function routeToSelectedPoint(target){
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    clearSteps();
    setPanelMessage('Connecting your location to the selected mapped route…');
    try{
      const origin = await window.DoloPawsTrailAccess.currentPosition(navigator);
      if(Number.isFinite(origin.accuracyM) && origin.accuracyM > window.DoloPawsTrailAccess.MAX_GPS_ACCURACY_M){
        setPanelMessage(`Your location is only accurate to about ${Math.round(origin.accuracyM)} m. Move into a clearer area and try again.`);
        setButtonLabel('Try again');
        return;
      }
      const entries = routingEntriesForPoint(target, origin);
      let plan = null;
      for(const entry of entries){
        const graph = await loadRoutingGraph(entry);
        plan = await window.DoloPawsTrailAccess.planMappedPoint(
          navigator,
          target,
          graph,
          window.DoloPawsFootpathRouter,
          navigator.userAgent,
          { origin, maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
        );
        if(plan.mode === 'mapped-point') break;
      }
      if(!plan){
        plan = await window.DoloPawsTrailAccess.planMappedPoint(
          navigator,
          target,
          null,
          window.DoloPawsFootpathRouter,
          navigator.userAgent,
          { origin, maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
        );
      }
      activePlan = plan;
      if(plan.mode === 'mapped-point'){
        showPlan(plan, true);
        renderSteps(plan.instructions);
        const targetSnap = plan.targetSnapDistanceM > 20
          ? ` The selected point was snapped ${formatApproachDistance(plan.targetSnapDistanceM / 1000)} to a connected path.`
          : '';
        setPanelMessage(`Mapped walking route · ${formatApproachDistance(plan.distanceKm)} to the selected route point.${targetSnap} Check local signs and temporary closures.`);
        setButtonLabel(defaultLabel);
        return;
      }
      if(plan.mode === 'external-point' && plan.allowed){
        showPlan(plan, false);
        setPanelMessage('This selected point is not connected to ORMA’s current walking graph. Your maps app can calculate the approach instead.');
        setButtonLabel('Open directions to selected point');
        return;
      }
      setPanelMessage('That point is outside ORMA’s current walking coverage. Choose a closer mapped route point.');
      setButtonLabel(defaultLabel);
    }catch(error){
      setPanelMessage('We could not calculate a route to that point. Check your location signal and try again.');
      setButtonLabel(defaultLabel);
    }finally{
      button.disabled = false;
      button.removeAttribute('aria-busy');
    }
  }

  button.addEventListener('click', async () => {
    if(activePlan && activePlan.url){
      window.open(activePlan.url, '_blank', 'noopener');
      return;
    }

    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    setButtonLabel('Calculating directions…');
    clearSteps();
    setPanelMessage('Checking your location against mapped walking paths…');
    try{
      const graph = await loadRoutingGraph();
      const plan = await window.DoloPawsTrailAccess.planTrailEntry(
        navigator,
        t,
        graph,
        window.DoloPawsFootpathRouter,
        navigator.userAgent,
        { maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
      );
      if(plan.mode === 'unreliable-location'){
        setPanelMessage(`Your location is only accurate to about ${Math.round(plan.accuracyM)} m. Move into a clearer area and try again.`);
        setButtonLabel('Try again');
        return;
      }
      if(plan.mode === 'mapped-footpath'){
        activePlan = plan;
        showPlan(plan, true);
        renderSteps(plan.instructions);
        const snapNote = plan.snapDistanceM > 20
          ? ` Your GPS is about ${formatApproachDistance(plan.snapDistanceM / 1000)} from the mapped path.`
          : '';
        setPanelMessage(`Mapped footpath route · ${formatApproachDistance(plan.distanceKm)} to the trail.${snapNote} Check local signs and temporary closures.`);
        setButtonLabel('Refresh walking route');
        return;
      }
      if(plan.mode === 'nearest-route'){
        activePlan = plan;
        showPlan(plan, false);
        const distanceM = plan.distanceKm * 1000;
        const overlapsFix = Number.isFinite(plan.accuracyM) && distanceM <= plan.accuracyM;
        setPanelMessage(overlapsFix
          ? 'Your location overlaps this trail. Open your maps app for the nearest mapped point, and check local signs before joining.'
          : `The nearest point on this trail is about ${formatApproachDistance(plan.distanceKm)} away. Your maps app will calculate the walk; check local signs and access before joining.`);
        setButtonLabel('Open directions to nearest trail point');
        return;
      }
      if(plan.mode === 'recommended-start' && plan.allowed){
        activePlan = plan;
        showPlan(plan, false);
        const startType = plan.targetKind === 'mapped-start' ? 'listed route start' : 'recommended start';
        setPanelMessage(`ORMA does not yet have a connected footpath network here. The ${startType} is about ${formatApproachDistance(plan.distanceKm)} away as the crow flies; your maps app will calculate the actual walk.`);
        setButtonLabel('Open directions to start');
        return;
      }
      if(plan.mode === 'recommended-start'){
        const startType = plan.targetKind === 'mapped-start' ? 'listed route start' : 'recommended start';
        setPanelMessage(`The ${startType} is about ${formatApproachDistance(plan.distanceKm)} away. Walking directions are available when you are within 5 km.`);
        setButtonLabel('Try again');
        return;
      }
      setPanelMessage('ORMA cannot identify a reliable access point for this trail yet. Use the recommended starting-point information below the map.');
      setButtonLabel(defaultLabel);
    }catch(error){
      const denied = error && (error.code === 1 || error.message === 'geolocation-unavailable');
      setPanelMessage(denied
        ? 'Allow location access to find the nearest point on this trail.'
        : 'We could not get a reliable location. Check your signal and try again.');
      setButtonLabel(defaultLabel);
    }finally{
      button.disabled = false;
      button.removeAttribute('aria-busy');
    }
  });
}

function sampledTrailPath(trail, maxPoints = 30){
  const path = Array.isArray(trail && trail.path) && trail.path.length
    ? trail.path
    : (trail && typeof trail.lat === 'number' && typeof trail.lng === 'number' ? [[trail.lat, trail.lng]] : []);
  if(path.length <= maxPoints) return path;
  const step = Math.ceil(path.length / maxPoints);
  const sampled = path.filter((_, index) => index % step === 0);
  if(sampled[sampled.length - 1] !== path[path.length - 1]) sampled.push(path[path.length - 1]);
  return sampled;
}

function nearbyTrailCandidates(currentTrail, allTrails, radiusKm = 25, limit = 5){
  const currentPath = sampledTrailPath(currentTrail);
  if(!currentPath.length) return [];
  return (allTrails || [])
    .filter(trail => trail && trail.id !== currentTrail.id && Array.isArray(trail.path) && trail.path.length > 1)
    .map(trail => {
      const candidatePath = sampledTrailPath(trail);
      let distanceKm = Infinity;
      let mapPoint = candidatePath[0];
      currentPath.forEach(currentPoint => candidatePath.forEach(candidatePoint => {
        const distance = mapDistanceKm(currentPoint, candidatePoint);
        if(distance < distanceKm){
          distanceKm = distance;
          mapPoint = candidatePoint;
        }
      }));
      return { trail, distanceKm, mapPoint };
    })
    .filter(item => item.distanceKm <= radiusKm)
    .sort((a, b) => a.distanceKm - b.distanceKm)
    .slice(0, limit);
}

// Finds the real point along an actual GPS path at a given fraction of its
// total length (0 = start, 1 = end). Used to place rifugi/water icons at
// their true position on the map, rather than guessing coordinates.
function pointAtFraction(path, fraction){
  const total = path.reduce((sum, p, i) => i === 0 ? 0 : sum + distMeters(path[i-1], p), 0);
  const target = total * Math.max(0, Math.min(1, fraction));
  let acc = 0;
  for(let i = 0; i < path.length - 1; i++){
    const seg = distMeters(path[i], path[i+1]);
    if(acc + seg >= target){
      const t = seg > 0 ? (target - acc) / seg : 0;
      return [
        path[i][0] + (path[i+1][0] - path[i][0]) * t,
        path[i][1] + (path[i+1][1] - path[i][1]) * t,
      ];
    }
    acc += seg;
  }
  return path[path.length - 1];
}

// Elevation profile chart with two-way hover sync: hovering the chart moves
// a cursor dot on the map; hovering near the route on the map highlights
// the matching point on the chart. Honest note on data granularity: this
// draws whatever is in t.elevationProfile — currently a sparse 5-6 point
// sample for hand-built trails, but it'll render just as correctly (and
// more smoothly) once a trail has real per-vertex elevation from the
// build-trail.mjs/build-route.mjs pipeline. The chart code doesn't care
// which source the numbers came from.
function setupElevationProfile(map, t){
  const panel = document.getElementById('tdElevationPanel');
  if(!Array.isArray(t.elevationProfile) || t.elevationProfile.length < 2 || !Array.isArray(t.path)){
    if(panel) panel.hidden = true;
    return;
  }

  const wrap = document.getElementById('elevationProfileWrap');
  const svg = document.getElementById('elevProf');
  const readout = document.getElementById('elevReadout');
  const liveReadout = document.getElementById('tdElevLive');
  const rangeReadout = document.getElementById('tdElevRange');
  wrap.hidden = false;

  const profile = t.elevationProfile; // [{km, elev}, ...]
  const totalKm = t.distance;
  const elevs = profile.map(p => p.elev);
  const eMin = Math.min(...elevs), eMax = Math.max(...elevs);
  if(rangeReadout) rangeReadout.textContent = `${Math.round(eMin)}–${Math.round(eMax)} m`;
  const startReadout = document.getElementById('tdElevStart');
  const highReadout = document.getElementById('tdElevHigh');
  const climbReadout = document.getElementById('tdElevClimb');
  const figures = document.getElementById('tdElevFigs');
  if(startReadout) startReadout.textContent = `${Math.round(profile[0].elev)} m`;
  if(highReadout) highReadout.textContent = `${Math.round(eMax)} m`;
  if(climbReadout) climbReadout.textContent = `${Math.round(Number(t.elevation) || 0)} m`;
  if(figures) figures.hidden = false;
  const VW = 1000, VH = 170, padL = 6, padR = 6, padT = 14, padB = 20;
  const x = km => padL + (km / totalKm) * (VW - padL - padR);
  const y = elev => padT + (1 - (elev - eMin) / ((eMax - eMin) || 1)) * (VH - padT - padB);

  const NS = 'http://www.w3.org/2000/svg';
  const mk = (tag, attrs) => {
    const el = document.createElementNS(NS, tag);
    for(const k in attrs) el.setAttribute(k, attrs[k]);
    return el;
  };

  let dLine = `M ${x(profile[0].km)} ${y(profile[0].elev)}`;
  profile.slice(1).forEach(p => { dLine += ` L ${x(p.km)} ${y(p.elev)}`; });
  const areaD = `${dLine} L ${x(profile[profile.length-1].km)} ${VH-padB} L ${x(profile[0].km)} ${VH-padB} Z`;
  svg.appendChild(mk('path', { d: areaD, fill: '#2E4034', opacity: '0.1' }));
  svg.appendChild(mk('path', { d: dLine, fill: 'none', stroke: '#2E4034', 'stroke-width': '2' }));

  [eMin, (eMin+eMax)/2, eMax].forEach(v => {
    svg.appendChild(mk('line', { x1: padL, x2: VW-padR, y1: y(v), y2: y(v), stroke: 'var(--paper-line)', 'stroke-width': '1' }));
    const label = mk('text', { x: padL+4, y: y(v)-3, 'font-size': '10', fill: 'var(--ink-soft)' });
    label.textContent = `${Math.round(v)} m`;
    svg.appendChild(label);
  });

  const cursorLine = mk('line', { y1: padT, y2: VH-padB, stroke: '#6FA8BE', 'stroke-width': '1.5', 'stroke-dasharray': '3 3', opacity: '0' });
  const cursorDot = mk('circle', { r: '4', fill: '#6FA8BE', stroke: '#fff', 'stroke-width': '1.5', opacity: '0' });
  svg.appendChild(cursorLine);
  svg.appendChild(cursorDot);

  // Map cursor marker
  map.addSource('elev-cursor', { type: 'geojson', data: { type: 'Point', coordinates: t.path[0].slice().reverse() } });
  map.addLayer({
    id: 'elev-cursor-layer', type: 'circle', source: 'elev-cursor',
    paint: { 'circle-radius': 6, 'circle-color': '#6FA8BE', 'circle-stroke-color': '#fff', 'circle-stroke-width': 2, 'circle-opacity': 0 },
  });

  function highlightAtKm(km){
    cursorLine.setAttribute('x1', x(km)); cursorLine.setAttribute('x2', x(km)); cursorLine.setAttribute('opacity', '1');
    // interpolate elevation for a smooth readout even between sparse samples
    let elev = profile[0].elev;
    for(let i = 1; i < profile.length; i++){
      if(km <= profile[i].km){
        const span = profile[i].km - profile[i-1].km;
        const frac = span > 0 ? (km - profile[i-1].km) / span : 0;
        elev = profile[i-1].elev + (profile[i].elev - profile[i-1].elev) * frac;
        break;
      }
    }
    cursorDot.setAttribute('cx', x(km)); cursorDot.setAttribute('cy', y(elev)); cursorDot.setAttribute('opacity', '1');
    readout.textContent = `${km.toFixed(1)} km · ${Math.round(elev)} m`;
    if(liveReadout) liveReadout.textContent = `${km.toFixed(1)} km · ~${Math.round(elev)} m route elevation`;

    const [lat, lng] = pointAtFraction(t.path, totalKm > 0 ? km / totalKm : 0);
    const src = map.getSource('elev-cursor');
    if(src){ src.setData({ type: 'Point', coordinates: [lng, lat] }); map.setPaintProperty('elev-cursor-layer', 'circle-opacity', 1); }
  }

  // Let hike-mode.js drive the same cursor from live GPS position.
  window._dolopawsElevHighlight = highlightAtKm;

  svg.addEventListener('mousemove', (ev) => {
    const rect = svg.getBoundingClientRect();
    const px = (ev.clientX - rect.left) / rect.width * VW;
    const km = Math.max(0, Math.min(totalKm, ((px - padL) / (VW - padL - padR)) * totalKm));
    highlightAtKm(km);
  });

  // Map -> chart: hovering near the route line highlights the matching point
  map.on('mousemove', (e) => {
    let bestKm = 0, bestDist = Infinity, acc = 0;
    for(let i = 0; i < t.path.length; i++){
      const d = distMeters([e.lngLat.lat, e.lngLat.lng], t.path[i]);
      if(d < bestDist){ bestDist = d; bestKm = (i / (t.path.length - 1)) * totalKm; }
    }
    if(bestDist < 80) highlightAtKm(bestKm); // only react when hovering near the actual route
  });
}

function makeIconEl(iconKey, bgColor){
  if(window.DoloPawsIcons) return window.DoloPawsIcons.createMarkerElement(iconKey, { color: bgColor });
  const fallback = document.createElement('div');
  fallback.className = 'dp-marker';
  fallback.style.background = bgColor;
  fallback.style.borderRadius = '50%';
  fallback.style.border = '2px solid #fff';
  fallback.textContent = '•';
  return fallback;
}

function addTerrainToggle(map, containerId, exaggeration, pitch3D, existingBtn){
  // With `existingBtn`, the toggle joins the Map · Satellite · 3D group.
  let btn = existingBtn || null;
  if(!btn){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.style.position = container.style.position || 'relative';
    btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = window.t('trail.view3d');
    btn.className = 'map-btn map-btn--terrain';
    container.appendChild(btn);
  }

  let elevationVisible = false; // clean, flat, label-first map by default
  let flatCamera = null;
  btn.addEventListener('click', () => {
    if(!elevationVisible){
      const currentZoom = typeof map.getZoom === 'function' ? map.getZoom() : 12.25;
      flatCamera = {
        center: typeof map.getCenter === 'function' ? map.getCenter() : undefined,
        zoom: currentZoom,
        bearing: typeof map.getBearing === 'function' ? map.getBearing() : undefined,
      };
      map.setTerrain({ source: 'terrain-dem-3d', exaggeration });
      if(!map.getLayer('hillshade-layer')){
        const beforeLayer = map.getLayer('waymarked-hiking-layer')
          ? 'waymarked-hiking-layer'
          : (map.getStyle().layers.find(layer => layer.type === 'symbol') || {}).id;
        map.addLayer({
          id: 'hillshade-layer',
          type: 'hillshade',
          source: 'terrain-dem',
          paint: {
            'hillshade-method': 'igor',
            'hillshade-exaggeration': 0.22,
            'hillshade-shadow-color': '#81907f',
            'hillshade-highlight-color': '#fffdf6',
            'hillshade-accent-color': '#60705f',
          },
        }, beforeLayer); // keep hillshade below the trail overlay and labels
      }
      // At close trail-detail zooms the camera can sit below a 2,000–3,000 m
      // terrain surface, blanking the map. Pull back to a safe planning zoom.
      map.easeTo({ pitch: pitch3D, zoom: Math.min(currentZoom, 12.25), duration: 500 });
      if(existingBtn){ btn.classList.add('on'); btn.setAttribute('aria-pressed', 'true'); }
      else btn.textContent = window.t('trail.viewFlat');
    } else {
      map.setTerrain(null);
      if(map.getLayer('hillshade-layer')) map.removeLayer('hillshade-layer');
      map.easeTo({
        pitch: 0,
        center: flatCamera && flatCamera.center,
        zoom: flatCamera && flatCamera.zoom,
        bearing: flatCamera && flatCamera.bearing,
        duration: 500,
      });
      if(existingBtn){ btn.classList.remove('on'); btn.setAttribute('aria-pressed', 'false'); }
      else btn.textContent = window.t('trail.view3d');
    }
    elevationVisible = !elevationVisible;
  });
}

function increaseLabelDensity(map){
  const layers = map.getStyle().layers || [];
  layers.forEach(layer => {
    if(layer.type !== 'symbol') return;
    const sl = layer['source-layer'];
    // Only boost PLACE names (towns, villages, hamlets) and mountain peaks:
    // clearing their minzoom makes them appear even when zoomed far out,
    // which is the effect that was actually wanted. Everything else (POI
    // icons, road names, house numbers) keeps the style's own collision
    // rules — forcing those all visible at once made town centers like
    // Canazei unreadably dense.
    if(sl !== 'place' && sl !== 'mountain_peak') return;
    try {
      map.setLayerZoomRange(layer.id, 0, 24);
      map.setLayoutProperty(layer.id, 'text-optional', true);
      // NOTE: deliberately NOT setting text-allow-overlap/icon-allow-overlap
      // anymore — that disabled collision detection entirely and was the
      // root cause of the overcrowded map. MapLibre's collision logic now
      // prunes overlapping labels automatically at every zoom.
    } catch(e) { /* some layers may not support one of these props — skip silently */ }
  });
}

function addTerrainSource(map){
  map.addSource('terrain-dem', {
    type: 'raster-dem',
    tiles: ['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],
    tileSize: 256,
    encoding: 'terrarium',
    maxzoom: 15,
  });
  // MapLibre renders more reliably when hillshade and 3D terrain do not
  // compete for the same raster-dem source.
  map.addSource('terrain-dem-3d', {
    type: 'raster-dem',
    tiles: ['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],
    tileSize: 256,
    encoding: 'terrarium',
    maxzoom: 15,
  });
}

// Always-on subtle relief, AllTrails-style: terrain reads at a glance even
// in flat mode. The 3D toggle's own stronger hillshade layers on top.
function addBaseHillshade(map, beforeId){
  if(map.getLayer('base-hillshade') || !map.getSource('terrain-dem')) return;
  map.addLayer({
    id: 'base-hillshade',
    type: 'hillshade',
    source: 'terrain-dem',
    paint: {
      'hillshade-exaggeration': 0.25,
      'hillshade-shadow-color': '#5A5548',
      'hillshade-method': 'igor',
    },
  }, beforeId && map.getLayer(beforeId) ? beforeId : undefined);
}

// Lifts on the trail detail map — ALL of them, same data as the homepage
// (the global `gondolas` array from trails-data.js). Lines and stations are
// GeoJSON layers rather than DOM markers, so rendering all ~700 lifts and
// ~1,400 stations costs nothing.
function escapeLiftPopupText(value){
  return String(value == null ? '' : value).replace(/[&<>"']/g,
    char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[char]);
}

function publicLiftNote(note){
  return escapeLiftPopupText(String(note || '')
    .replace(/Operating season not recorded\s*[—-]\s*check directly with the operator before planning around it\.\s*/gi, '')
    .replace(/Station order \(from\/to\) reflects raw OSM way direction, NOT independently verified against elevation\s*-\s*treat the endpoint labels as unconfirmed for this batch\.\s*/gi, '')
    .trim());
}

function renderAllLifts(map, options){
  if (typeof gondolas === 'undefined' || !Array.isArray(gondolas) || !gondolas.length) return;
  if (map.getSource('detail-gondolas')) return;
  const visibility = options && options.visible ? 'visible' : 'none';

  const lineFeatures = [], stationFeatures = [];
  gondolas.forEach(g => {
    if (!g.from || !g.to || typeof g.from.lat !== 'number' || typeof g.to.lat !== 'number') return;
    lineFeatures.push({
      type: 'Feature',
      properties: { name: g.name, note: g.note || '', status: g.status },
      geometry: { type: 'LineString', coordinates: [[g.from.lng, g.from.lat], [g.to.lng, g.to.lat]] },
    });
    [g.from, g.to].forEach(st => {
      stationFeatures.push({
        type: 'Feature',
        properties: { name: g.name, note: g.note || '' },
        geometry: { type: 'Point', coordinates: [st.lng, st.lat] },
      });
    });
  });

  map.addSource('detail-gondolas', { type: 'geojson', data: { type: 'FeatureCollection', features: lineFeatures } });
  map.addLayer({
    id: 'detail-gondolas-line',
    type: 'line',
    source: 'detail-gondolas',
    layout: { 'line-join': 'round', 'line-cap': 'round', visibility },
    paint: {
      'line-color': ['match', ['get', 'status'], 'summer', '#4E90A8', 'no-summer', '#9C3A25', '#5A5548'],
      'line-width': 1.5,
      'line-opacity': 0.9,
      'line-dasharray': ['match', ['get', 'status'], 'summer', ['literal', [1, 0]], ['literal', [2, 1]]],
    },
  });
  map.addSource('detail-gondola-stations', { type: 'geojson', data: { type: 'FeatureCollection', features: stationFeatures } });
  if(window.DoloPawsIcons){
    map.addLayer({
      id: 'detail-gondola-stations-layer',
      type: 'symbol',
      source: 'detail-gondola-stations',
      layout: {
        'icon-image': window.DoloPawsIcons.getMapImageName('lifts'),
        'icon-size': 1,
        visibility,
      },
    });
  } else {
    map.addLayer({
      id: 'detail-gondola-stations-layer',
      type: 'circle',
      source: 'detail-gondola-stations',
      layout: { visibility },
      paint: { 'circle-radius': 5, 'circle-color': '#4E90A8', 'circle-stroke-width': 1.5, 'circle-stroke-color': '#fff' },
    });
  }

  ['detail-gondolas-line', 'detail-gondola-stations-layer'].forEach(id => {
    map.on('mouseenter', id, () => { map.getCanvas().style.cursor = 'pointer'; });
    map.on('mouseleave', id, () => { map.getCanvas().style.cursor = ''; });
    map.on('click', id, (e) => {
      const p = e.features[0].properties;
      const note = publicLiftNote(p.note);
      new maplibregl.Popup({ offset: 10 })
        .setLngLat(e.lngLat)
        .setHTML(`<b>🚡 ${escapeLiftPopupText(p.name)}</b>${note ? '<br>' + note : ''}`)
        .addTo(map);
    });
  });
}

// ============================================================
// IMPORTED CIRCUITS — start where you can actually park.
// OSM route relations have no official start point: the import stitches
// their segments into one line and begins wherever stitching happened to
// start, so a loop's km 0 can land mid-slope, far from any access.
// Before rendering, look up real amenity=parking spots around the route
// (Overpass, cached locally for 30 days) and rotate the loop so km 0
// sits at the path point nearest a parking area. Everything downstream —
// 🚩 flag, directions, arrows, weather anchor, hike mode — follows the
// rotated order automatically. Falls back silently to the imported order
// when no parking is close enough or the lookup fails or times out.
// ============================================================
const PARK_CACHE_TTL = 30 * 24 * 3600 * 1000;
const PARK_MAX_DIST_M = 350;      // parking must be this close to the route
// Parking refinement is helpful, but it is not allowed to delay the first
// trail render. The result is cached for the next visit if it arrives later.
const PARK_LOOKUP_WAIT_MS = 0;

function isLoopPath(path){
  return Array.isArray(path) && path.length > 20 &&
    distMeters(path[0], path[path.length - 1]) < 250;
}

function fetchNearbyParking(path){
  let minLat = 90, maxLat = -90, minLng = 180, maxLng = -180;
  path.forEach(([lat, lng]) => {
    if(lat < minLat) minLat = lat;
    if(lat > maxLat) maxLat = lat;
    if(lng < minLng) minLng = lng;
    if(lng > maxLng) maxLng = lng;
  });
  const PAD = 0.008; // ~800 m beyond the route's bounding box
  const bbox = `${minLat - PAD},${minLng - PAD},${maxLat + PAD},${maxLng + PAD}`;
  const query = `[out:json][timeout:8];(node["amenity"="parking"](${bbox});way["amenity"="parking"](${bbox}););out center 60;`;
  const mirrors = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter'];
  const tryMirror = (i) => fetch(mirrors[i], {
    method: 'POST',
    body: 'data=' + encodeURIComponent(query),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  })
    .then(r => { if(!r.ok) throw new Error('overpass ' + r.status); return r.json(); })
    .catch(err => { if(i + 1 < mirrors.length) return tryMirror(i + 1); throw err; });
  return tryMirror(0).then(data => (data.elements || []).map(el => {
    const lat = el.lat != null ? el.lat : (el.center && el.center.lat);
    const lng = el.lon != null ? el.lon : (el.center && el.center.lon);
    return (lat == null || lng == null) ? null : { lat, lng, name: (el.tags && el.tags.name) || '' };
  }).filter(Boolean));
}

function nearestPathIndex(path, pt){
  let best = 0, bestD = Infinity;
  for(let i = 0; i < path.length; i++){
    const d = distMeters(path[i], [pt.lat, pt.lng]);
    if(d < bestD){ bestD = d; best = i; }
  }
  return { index: best, dist: bestD };
}

function applyLoopRotation(trail, rot){
  if(rot.index > 0){
    const path = trail.path;
    const closed = distMeters(path[0], path[path.length - 1]) < 30;
    const open = closed ? path.slice(0, -1) : path.slice();
    const rotated = open.slice(rot.index).concat(open.slice(0, rot.index));
    rotated.push(rotated[0].slice()); // close the loop at the new start
    trail.path = rotated;
  }
  trail.startPoint = {
    lat: trail.path[0][0],
    lng: trail.path[0][1],
    label: rot.name
      ? window.t('trail.startParkName', { name: rot.name })
      : window.t('trail.startParking'),
  };
  trail.lat = trail.path[0][0];
  trail.lng = trail.path[0][1];
}

function improveLoopStart(trail, options){
  if(!trail || trail.curated !== false || !isLoopPath(trail.path)) return Promise.resolve();
  const deferOnMiss = !!(options && options.deferOnMiss);
  const cacheKey = 'dolopaws-parkstart-' + trail.id;
  try {
    const cached = JSON.parse(localStorage.getItem(cacheKey) || 'null');
    if(cached && Date.now() - cached.at < PARK_CACHE_TTL){
      if(cached.rot) applyLoopRotation(trail, cached.rot);
      return Promise.resolve();
    }
  } catch (e) { /* unreadable cache — just refetch */ }

  const lookup = fetchNearbyParking(trail.path).then(parkings => {
    let best = null;
    parkings.forEach(p => {
      const near = nearestPathIndex(trail.path, p);
      if(near.dist <= PARK_MAX_DIST_M && (!best || near.dist < best.dist)){
        best = { index: near.index, dist: near.dist, name: p.name };
      }
    });
    const rot = best ? { index: best.index, name: best.name } : null;
    try { localStorage.setItem(cacheKey, JSON.stringify({ at: Date.now(), rot })); } catch (e) {}
    return rot;
  }).catch(() => null);

  // A trail-detail navigation must never wait on Overpass. On the first visit,
  // let the lookup finish into the cache while the page renders immediately;
  // later visits can apply that cached start synchronously above.
  if(deferOnMiss) return Promise.resolve();

  // Non-navigation callers may still opt into the former bounded wait.
  const timeout = new Promise(res => setTimeout(() => res('timeout'), PARK_LOOKUP_WAIT_MS));
  return Promise.race([lookup, timeout]).then(rot => {
    if(rot && rot !== 'timeout') applyLoopRotation(trail, rot);
  });
}


// ============================================================
// "FROM PARKING TO PAWS" — one named, km-ordered itinerary that
// replaces the separate directions/rifugi/water lists. Base steps
// (parking, start, decision points, finish) render immediately;
// named amenities from the OSM files arrive asynchronously via
// detail-pois.js callbacks and slot in by km.
// ============================================================
const itin = { trail: null, items: [], cumKm: null };

// Curated trail data stores labels in English; translate the known
// templates on the fly in Italian mode (same approach as imported descs).
function trLabel(label){
  if(!label || (window.DoloPawsI18n && window.DoloPawsI18n.lang) !== 'it') return label;
  const RULES = [
    [/^Start here — main parking area at (.+)$/, 'Parti qui — parcheggio principale a $1'],
    [/^Start here — main lake access & parking, by (.+)$/, 'Parti qui — accesso principale al lago e parcheggio, presso $1'],
    [/^Route start per OpenStreetMap — best parking\/access not yet verified$/, 'Inizio del percorso secondo OpenStreetMap — parcheggio/accesso migliore non ancora verificato'],
    [/^Lakeside fountain$/, 'Fontana in riva al lago'],
    [/^Trailhead fountain$/, 'Fontana alla partenza'],
    [/^Village fountain$/, 'Fontana del paese'],
    [/^Waterfall stream$/, 'Torrente della cascata'],
    [/^Stream crossing$/, 'Attraversamento del torrente'],
    [/^Drinking water \(OSM-verified location\)$/, 'Acqua potabile (posizione verificata su OSM)'],
    [/^Mountain\/upper station$/, 'Stazione a monte'],
    [/^Valley\/lower station$/, 'Stazione a valle'],
  ];
  for(const [re, out] of RULES){ if(re.test(label)) return label.replace(re, out); }
  return label;
}

function itinIcon(kind){
  const S = 'width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" style="flex:none;"';
  if(kind === 'park') return `<svg ${S}><rect x="3" y="3" width="18" height="18" rx="5" fill="#378ADD"/><path d="M9 17V7h4a3.2 3.2 0 010 6.4H9" fill="none" stroke="#fff" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  if(kind === 'flag') return `<svg ${S}><path d="M7 21V4" stroke="#2E4034" stroke-width="2" stroke-linecap="round"/><path d="M7 5h10l-2.4 3.5L17 12H7z" fill="#E24B4A"/></svg>`;
  if(kind === 'food') return `<svg ${S}><path d="M5 9h11v6a4 4 0 01-4 4H9a4 4 0 01-4-4z" fill="#BA7517"/><path d="M16 10h1.6a2.2 2.2 0 010 4.4H16" fill="none" stroke="#BA7517" stroke-width="1.8"/><path d="M8.5 6.5c0-1 .8-1.4.8-2.3M12 6.5c0-1 .8-1.4.8-2.3" stroke="#BA7517" stroke-width="1.5" stroke-linecap="round" fill="none"/></svg>`;
  if(kind === 'hut') return `<svg ${S}><path d="M4 11l8-7 8 7" fill="none" stroke="#8A5A16" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M6 10v9h12v-9" fill="#D6A038" stroke="#8A5A16" stroke-width="1.6" stroke-linejoin="round"/><path d="M10 19v-5h4v5" fill="#8A5A16"/></svg>`;
  if(kind === 'water') return `<svg ${S}><path d="M12 3c3 3.6 4.8 6.3 4.8 8.8a4.8 4.8 0 11-9.6 0C7.2 9.3 9 6.6 12 3z" fill="#378ADD"/></svg>`;
  if(kind === 'switch') return `<svg ${S}><path d="M12 20v-8M12 12L6.5 6M12 12l5.5-6" fill="none" stroke="#7F77DD" stroke-width="2.2" stroke-linecap="round"/><circle cx="6.5" cy="6" r="1.7" fill="#7F77DD"/><circle cx="17.5" cy="6" r="1.7" fill="#AFA9EC"/></svg>`;
  if(kind === 'view') return `<svg ${S}><path d="M5 8h3l1.2-2h5.6L16 8h3v10H5z" fill="none" stroke="#28736B" stroke-width="2" stroke-linejoin="round"/><circle cx="12" cy="13" r="3" fill="none" stroke="#28736B" stroke-width="2"/></svg>`;
  if(kind === 'picnic') return `<svg ${S}><path d="M4 9.5h16M8 9.5 5.5 18M16 9.5l2.5 8.5M6.6 14.5h10.8" fill="none" stroke="#4E7256" stroke-width="2" stroke-linecap="round"/></svg>`;
  if(kind === 'sight') return `<svg ${S}><path d="M8 20V4.5" stroke="#5A5548" stroke-width="2" stroke-linecap="round"/><path d="M8 5.5h8.5l-2.1 3 2.1 3H8z" fill="#5A5548"/></svg>`;
  return `<svg ${S}><ellipse cx="12" cy="15.5" rx="4" ry="3.4" fill="#1D9E75"/><ellipse cx="7" cy="10.8" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="10.5" cy="8.6" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="14" cy="8.6" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="17.5" cy="10.8" rx="1.5" ry="2" fill="#5DCAA5"/></svg>`;
}

function itinCumKm(path){
  const cum = [0];
  for(let i = 1; i < path.length; i++) cum.push(cum[i-1] + distMeters(path[i-1], path[i]) / 1000);
  return cum;
}

function itinEsc(x){
  return String(x).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
}

function itinRender(){
  const box = document.getElementById('trailItinerary');
  if(!box || !itin.trail) return;
  const items = itin.items.slice().sort((a, b) => a.sort - b.sort);
  box.innerHTML = items.map(it =>
    `<div class="itin-row">${itinIcon(it.icon)}<span>${it.html}</span></div>`).join('');
}

function itinAdd(icon, sort, html){
  itin.items.push({ icon, sort, html });
}

function itinKmLabel(km){
  return `<b style="font-weight:700;">Km ${km % 1 === 0 ? km : km.toFixed(1)}</b>`;
}

function buildItinerary(t){
  itin.trail = t;
  itin.items = [];
  itin.cumKm = Array.isArray(t.path) && t.path.length > 1 ? itinCumKm(t.path) : null;
  const isLoop = Array.isArray(t.path) && t.path.length > 1
    && distMeters(t.path[0], t.path[t.path.length-1]) < 200;

  // 1. Parking / access — the named startPoint label plus a directions
  // link into whatever navigation app this device prefers: Apple Maps on
  // iOS/macOS, Google Maps elsewhere. Neutral label, destination pre-filled.
  const sp = t.startPoint || { lat: t.lat, lng: t.lng, label: '' };
  const isApple = /iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent);
  const mapsUrl = isApple
    ? `https://maps.apple.com/?daddr=${sp.lat},${sp.lng}`
    : `https://www.google.com/maps/dir/?api=1&destination=${sp.lat},${sp.lng}`;
  const parkLabel = sp.label ? itinEsc(trLabel(trustedStartLabel(t, sp.label))) : window.t('trail.itinParkFallback');
  itinAdd('park', -2, `${parkLabel} · <a href="${mapsUrl}" target="_blank" rel="noopener">${window.t('trail.openMaps')}</a>`);

  // 2. The start flag.
  itinAdd('flag', -1, window.t('trail.itinStart'));

  // 3. Curated rifugi and water points (they carry real names + km).
  (Array.isArray(t.rifugi) ? t.rifugi : []).forEach(r => {
    if(r.km > 0) itinAdd('hut', r.km, `${itinKmLabel(r.km)} — ${itinEsc(r.name)}`);
  });
  (Array.isArray(t.waterSources) ? t.waterSources : []).forEach(w => {
    if(w.km > 0) itinAdd('water', w.km, `${itinKmLabel(w.km)} — ${itinEsc(trLabel(trustedWaterLabel(t, w.label)))}`);
  });

  // 4. Decision points — where the route switches numbered trails.
  (Array.isArray(t.decisionPoints) ? t.decisionPoints : []).forEach(d => {
    itinAdd('switch', d.km, `${itinKmLabel(d.km)} — ${itinEsc(d.instruction)}`);
  });

  // 5. Closing step.
  itinAdd('paw', 1e9, isLoop
    ? window.t('trail.itinLoopEnd', {d: t.distance})
    : window.t('trail.itinEnd', {d: t.distance}));

  itinRender();

  // 6. Named amenities from the OSM datasets, joined to their km on the
  // route (only places within ~120 m of the actual path).
  const MAX_OFF_M = 120;
  function kmOnPath(lat, lng){
    if(!itin.cumKm) return null;
    let best = -1, bestD = Infinity;
    for(let i = 0; i < t.path.length; i++){
      const d = distMeters(t.path[i], [lat, lng]);
      if(d < bestD){ bestD = d; best = i; }
    }
    return bestD <= MAX_OFF_M ? { km: itin.cumKm[best], off: bestD } : null;
  }
  const seen = new Set(itin.items.map(i => i.html.toLowerCase()));

  window.onDetailPoisReady = (features) => {
    let added = 0;
    (features || []).forEach(f => {
      if(added >= 4) return;
      const p = f.properties || {};
      if(!p.name) return;
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const nameKey = p.name.toLowerCase();
      if([...seen].some(h => h.includes(nameKey))) return;
      const isHut = p.tourism === 'alpine_hut' || p.tourism === 'wilderness_hut' || p.amenity === 'shelter';
      itinAdd(isHut ? 'hut' : 'food', hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)} — ${itinEsc(p.name)}`);
      seen.add(nameKey);
      added++;
    });
    if(added) itinRender();
  };

  window.onDetailWaterReady = (features) => {
    // Only fill from OSM when the trail has no curated water list.
    if(Array.isArray(t.waterSources) && t.waterSources.length) return;
    let added = 0;
    (features || []).forEach(f => {
      if(added >= 2) return;
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const label = (f.properties && f.properties.name) ? f.properties.name : window.t('legend.water');
      itinAdd('water', hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)} — ${itinEsc(label)}`);
      added++;
    });
    if(added) itinRender();
  };

  // Viewpoints, picnic spots and named sights from the trail-corridor
  // amenity sweep — a couple of each, placed at their km on the route.
  window.onDetailPlacesReady = (features) => {
    const plainT = (key, fb) => {
      if(!window.t) return fb;
      const v = window.t(key);
      return v === key ? fb : v;
    };
    const CAP = { viewpoint: 2, picnic: 2, sight: 2 };
    const added = { viewpoint: 0, picnic: 0, sight: 0 };
    let any = 0;
    (features || []).forEach(f => {
      const p = f.properties || {};
      const kind = p.kind;
      if(!(kind in CAP) || added[kind] >= CAP[kind]) return;
      if(kind === 'sight' && !p.name) return;   // unnamed crosses are noise
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const label = p.name
        || (kind === 'viewpoint' ? plainT('poi.viewpoint', 'Viewpoint') : plainT('poi.picnic', 'Picnic spot'));
      const nameKey = label.toLowerCase();
      if([...seen].some(h => h.includes(nameKey))) return;
      const icon = kind === 'viewpoint' ? 'view' : (kind === 'picnic' ? 'picnic' : 'sight');
      itinAdd(icon, hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)} — ${itinEsc(label)}`);
      seen.add(nameKey);
      added[kind]++;
      any++;
    });
    if(any) itinRender();
  };
}

const params = new URLSearchParams(window.location.search);
const trailId = params.get('id');
const trailReturnTarget = params.get('from');
const hikeDeepLinkRequested = params.get('hike') === '1';
let pendingTrailAction = params.get('action');
let trailActionConsumed = false;

window.DoloPawsTrailAction = {
  request(action){
    const url = new URL(window.location.href);
    url.searchParams.set('action', action);
    window.history.replaceState(null, '', url.pathname.split('/').pop() + url.search + url.hash);
    pendingTrailAction = action;
    trailActionConsumed = false;
    if(window.DoloPawsGuestContext){
      window.DoloPawsGuestContext.captureCurrent(action, trailId);
    }
    if(window.DoloPawsAuthUI) window.DoloPawsAuthUI.openLogin();
  },
  consume(action){
    if(trailActionConsumed || pendingTrailAction !== action) return false;
    if(window.DoloPawsGuestContext){
      const context = window.DoloPawsGuestContext.consumeAction(
        window.localStorage,
        action,
        trailId
      );
      if(!context){
        trailActionConsumed = true;
        pendingTrailAction = null;
        const staleUrl = new URL(window.location.href);
        staleUrl.searchParams.delete('action');
        window.history.replaceState(
          null,
          '',
          staleUrl.pathname.split('/').pop() + staleUrl.search + staleUrl.hash
        );
        return false;
      }
    }
    trailActionConsumed = true;
    pendingTrailAction = null;
    const url = new URL(window.location.href);
    url.searchParams.delete('action');
    window.history.replaceState(null, '', url.pathname.split('/').pop() + url.search + url.hash);
    return true;
  },
  get pending(){ return pendingTrailAction; },
};

function safeTrailReturn(value){
  if(!value || /^(?:[a-z]+:|\/\/|\/)/i.test(value)) return '';
  return /^(?:browse-trails|compare|saved|journal)\.html(?:\?[^#]*)?(?:#.*)?$/i.test(value) ? value : '';
}

let trailInitStarted = false;
function init(){
  if(trailInitStarted) return;
  trailInitStarted = true;
  if(window.DoloPawsRegions && typeof trails !== 'undefined') window.DoloPawsRegions.assign(trails);
  const trail = (typeof trails !== 'undefined') ? trails.find(x => x.id === trailId) : null;

  if(!trail){
    document.title = window.t('trail.notFound') + ' | ORMA';
    const wrap = document.querySelector('.td-wrap');
    if(wrap){
      wrap.innerHTML = `
        <div style="max-width:620px;margin:48px auto;text-align:center;">
          <h1>${window.t('trail.notFound')}</h1>
          <p style="margin:14px 0 24px;color:var(--ink-soft);">${window.t('trail.notFoundSub')}</p>
          <div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;">
            <a class="auth-submit" href="browse-trails.html" style="display:inline-block;width:auto;padding:11px 22px;text-decoration:none;">Browse trails</a>
            <a class="fav-btn" href="/" style="display:inline-block;padding:11px 22px;text-decoration:none;">Go to homepage</a>
          </div>
        </div>`;
    }
    return;
  }

  // Cached real-world starts are applied before rendering. A cache miss starts
  // the lookup in the background so a slow third-party service cannot hold a
  // mobile navigation on the loading shell.
  improveLoopStart(trail, { deferOnMiss:true })
    .then(() => renderTrail(trail), () => renderTrail(trail));
}

function renderTrail(t){
  if(window.DoloPawsMetricFunnel){
    const profilePresent = (() => {
      try{ return !!JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null'); }
      catch(error){ return false; }
    })();
    const decisionProperties = {
      trailId:t.id,
      verificationStatus:t.curated === false ? 'estimated' : 'dolopaws_vetted',
      warningCount:Array.isArray(t.surfaceHazards) ? t.surfaceHazards.length : 0,
      profilePresent,
    };
    window.DoloPawsMetricFunnel.recordOnce(
      'trail-opened', t.id, 'trail_decision', 'opened', decisionProperties
    );
    window.DoloPawsMetricFunnel.recordOnce(
      'explanation-viewed', t.id, 'trail_decision', 'explanation_viewed', decisionProperties
    );
  }
  buildItinerary(t);
  const hasRoutePath = Array.isArray(t.path) && t.path.length > 1;
  const routeDataNotice = document.getElementById('routeDataNotice');
  if(routeDataNotice){
    routeDataNotice.hidden = hasRoutePath;
    routeDataNotice.textContent = window.t('trail.routeUnavailable');
  }
  const breadcrumb = document.getElementById('tdBreadcrumb');
  const returnTarget = safeTrailReturn(trailReturnTarget);
  if(breadcrumb && returnTarget){
    breadcrumb.href = returnTarget;
    breadcrumb.textContent = returnTarget.startsWith('saved.html') ? '← Back to saved trails'
      : returnTarget.startsWith('journal.html') ? '← Back to journal'
      : returnTarget.startsWith('compare.html') ? '← Back to comparison'
      : '← Back to trail results';
  }
  const logWalkBtn = document.getElementById('logWalkBtn');
  if(logWalkBtn){
    const journalReturn = encodeURIComponent(`trail.html?id=${encodeURIComponent(t.id)}`);
    logWalkBtn.href = `journal.html?trail=${encodeURIComponent(t.id)}&from=${journalReturn}`;
  }
  // Do not reserve an empty elevation panel for routes without profile data.
  const elevationCard = document.getElementById('tdElevationPanel');
  const hasElevationProfile = Array.isArray(t.elevationProfile) && t.elevationProfile.length > 1;
  if(elevationCard){
    elevationCard.hidden = !hasElevationProfile;
    const experienceGrid = elevationCard.closest('.trail-experience-grid');
    if(experienceGrid) experienceGrid.classList.toggle('trail-experience-grid--itinerary-only', !hasElevationProfile);
  }
  document.title = `${t.name} | ORMA`;
  document.getElementById('pageTitle').textContent = `${t.name} | ORMA`;
  document.getElementById('trailName').textContent = t.name;
  document.getElementById('trailName').removeAttribute('aria-busy');
  // Photo-backed hero (per prototype): trail photo under a dark gradient.
  // Trails without an image keep the flat dark hero.
  if(t.imageIcon){
    const heroPhoto = document.getElementById('tdHeroPhoto');
    const heroVeil = document.getElementById('tdHeroVeil');
    if(heroPhoto && heroVeil){
      const responsivePhotoByTrailId = {
        'lago-braies':'images/lago-di-braies.webp',
        'lago-carezza':'images/lago-di-carezza.webp',
        'osm-16322228':'images/boucle-du-marais-des-chassettes.webp',
        'osm-3982382':'images/circuit-beatrice-de-savoie.webp',
        'osm-10116380':'images/itineraire-decouverte-de-la-nature.webp',
      };
      const responsiveSource = responsivePhotoByTrailId[t.id] || t.imageIcon;
      const responsiveWidths = {
        'images/lago-di-braies.webp':[480,900],
        'images/lago-di-carezza.webp':[480,900],
        'images/boucle-du-marais-des-chassettes.webp':[480,960,1280],
        'images/circuit-beatrice-de-savoie.webp':[480,960,1280],
        'images/itineraire-decouverte-de-la-nature.webp':[480,960,1280],
      }[responsiveSource];
      if(responsiveWidths){
        const stem = responsiveSource.replace(/\.webp$/, '');
        heroPhoto.src = `${stem}.jpg`;
        heroPhoto.srcset = responsiveWidths.map((width, index) =>
          `${width === 900 ? responsiveSource : `${stem}-${width}.webp`} ${width}w`
        ).join(', ');
        heroPhoto.sizes = '(max-width: 700px) 100vw, 1200px';
      } else if(/^https:\/\/commons\.wikimedia\.org\/wiki\/Special:Redirect\/file\//i.test(t.imageIcon)){
        const separator = t.imageIcon.includes('?') ? '&' : '?';
        heroPhoto.src = `${t.imageIcon}${separator}width=960`;
        heroPhoto.srcset = [480, 960, 1600].map(width =>
          `${t.imageIcon}${separator}width=${width} ${width}w`
        ).join(', ');
        heroPhoto.sizes = '(max-width: 700px) 100vw, 1200px';
      } else {
        heroPhoto.src = t.imageIcon;
      }
      heroPhoto.decoding = 'async';
      heroPhoto.fetchPriority = 'high';
      heroPhoto.alt = t.imageAlt || `${t.name} trail photograph`;
      heroPhoto.hidden = false;
      heroVeil.hidden = false;
      const creditEl = document.getElementById('tdHeroCredit');
      const creditText = document.getElementById('tdHeroCreditText');
      const credit = window.DoloPawsPhotoProvenance
        ? window.DoloPawsPhotoProvenance.heroCredit(t)
        : null;
      if(creditEl && creditText && credit){
        creditEl.open=false;
        creditText.replaceChildren();
        if(credit.url){
          const link=document.createElement('a');
          link.href=credit.url;link.target='_blank';link.rel='noopener nofollow';link.textContent=credit.label;
          creditText.appendChild(link);
        }else creditText.textContent=credit.label;
        creditEl.hidden=false;
      }
    }
  }
  document.getElementById('trailMeta').textContent =
    `${t.area} · ${t.distance} km · ${t.elevation} m gain · ${t.hours} h · ${t.terrainType}`;
  document.getElementById('trailBadges').innerHTML =
    trailProductBadge(t.safetyLevel, trailSafetyLabel(t)) +
    (t.paid ? trailProductBadge('neutral', window.t('card.paid')) : '');
  const rawDescription = trField(t, 'desc');
  const descriptionSentences = String(rawDescription).match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [rawDescription];
  let conciseDescription = '';
  for (const sentence of descriptionSentences) {
    const candidate = `${conciseDescription}${conciseDescription ? ' ' : ''}${sentence.trim()}`;
    if (candidate.length > 330) break;
    conciseDescription = candidate;
    if (conciseDescription.length > 190) break;
  }
  if (!conciseDescription) conciseDescription = String(rawDescription).slice(0, 327).trimEnd() + (String(rawDescription).length > 327 ? '…' : '');
  document.getElementById('trailDesc').textContent = conciseDescription;
  document.getElementById('trailTips').textContent = t.tips ? window.t('trail.tip', {tip: trField(t, 'tips')}) : '';

  // Community v0: "N dogs hiked this trail this week" — anonymous counts
  // from hike-mode starts. Deliberately renders NOTHING at zero: an empty
  // trail should look quiet, not dead.
  function showWeeklyHikes(){
    if (!window.DoloPawsCommunity) return;
    window.DoloPawsCommunity.getWeeklyHikeCount(t.id).then(n => {
      if (!n || n < 1) return;
      const chip = document.getElementById('dogsChip');
      if (!chip) return;
      const weeklyLabel = n === 1 ? window.t('trail.dogsWeek1') : window.t('trail.dogsWeek', {n});
      chip.innerHTML = window.DoloPawsIcons
        ? window.DoloPawsIcons.renderIconSvg('dog', { mode:'inline', color:'currentColor', size:14 }) + `<span>${itinEsc(weeklyLabel)}</span>`
        : itinEsc(weeklyLabel);
      chip.classList.add('dp-inline-status');
      chip.hidden = false;
    });
  }
  if (window.DoloPawsCommunity) showWeeklyHikes();
  else window.addEventListener('dolopaws-auth-ready', showWeeklyHikes, { once: true });

  // Provenance banner: imported (OSM) vs verified (curated) trails.
  (function () {
    const descEl = document.getElementById('trailDesc');
    if (!descEl || document.getElementById('osmProvenance')) return;
    const box = document.createElement('div');
    box.id = 'osmProvenance';
    box.className = 'trail-provenance';
    const trust = window.DoloPawsTrailTrust;
    const provStyle = trust && trust.tierBadgeStyle ? trust.tierBadgeStyle(t) : (t.curated === false ? 'imported' : 'verified');
    const provenanceIcon = window.DoloPawsIcons
      ? window.DoloPawsIcons.renderIconSvg(provStyle, { mode:'inline', color:'currentColor', size:16 })
      : '';
    box.style.cssText = 'margin:10px 0 14px;padding:10px 14px;border-left:4px solid #2E4034;background:#eef3ef;border-radius:6px;font-size:13px;line-height:1.5;';
    box.innerHTML = provenanceIcon + '<strong>Trail planning information.</strong> Based on mapped route data and available ORMA sources. Conditions can change, so check locally before setting out.';
    descEl.parentNode.insertBefore(box, descEl);

    // Trail hazards — surfaceHazards used to feed only the match scoring;
    // surface them to the reader too, right under the provenance banner.
    const surfaceVerified = !trust || !trust.categoryVerified || trust.categoryVerified(t, 'surfaceHazards');
    if (surfaceVerified && Array.isArray(t.surfaceHazards) && t.surfaceHazards.length && !document.getElementById('trailHazards')) {
      const hz = document.createElement('div');
      hz.id = 'trailHazards';
      hz.style.cssText = 'margin:0 0 14px;padding:10px 14px;border-left:4px solid #9C3A25;background:#faeeea;border-radius:6px;font-size:13px;line-height:1.5;';
      const warningIcon = window.DoloPawsIcons ? window.DoloPawsIcons.renderIconSvg('warning', { mode:'inline', color:'currentColor', size:16 }) : '';
      hz.innerHTML = '<strong class="dp-inline-status">' + warningIcon + '<span>' + itinEsc(window.t('trail.hazardsTitle') || 'Trail hazards') + '</span></strong><ul style="margin:6px 0 0 18px;padding:0;">'
        + t.surfaceHazards.map(h => '<li>' + String(h).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])) + '</li>').join('')
        + '</ul>';
      descEl.parentNode.insertBefore(hz, descEl);
    }
  })();

  // Quick facts — ascent/descent, highest/lowest point.
  // Note: summing the sparse elevationProfile points (usually just 5-6
  // samples) systematically UNDERSTATES real ascent, since it misses the
  // smaller ups and downs between samples — confirmed by comparing against
  // Tre Cime's already-researched 430m gain figure, which came out much
  // higher than summing its profile points did. Using the existing
  // `elevation` field for ascent is more trustworthy, and since every trail
  // here is a loop (same start/end point), descent is the same figure —
  // net elevation change over a full loop is ~0 by definition.
  // Facts live inside the dark hero now — one place, no duplicates.
  (function(){
    const factsEl = document.getElementById('trailFacts');
    if(!factsEl) return;
    const facts = [
      [`${t.distance} km`, window.t('trail.fact.distance')],
      [`${t.elevation} m`, window.t('trail.fact.ascent')],
      [`${t.hours} h`, window.t('trail.fact.duration')],
    ].filter(([val]) => !/^null|^undefined/.test(val)); // hide facts the data honestly lacks
    if(Array.isArray(t.elevationProfile) && t.elevationProfile.length > 1){
      facts.splice(2, 0, [`${Math.max(...t.elevationProfile.map(p => p.elev))} m`, window.t('trail.fact.high')]);
    }
    // Difficulty cell — mirrors the homepage's derivation from real fields so
    // the hero stat strip matches the design's five-cell layout.
    (function(){
      const asc = Number(t.elevation) || 0;
      const rank = Number(t.terrainRank) || 0;
      const km = Number(t.distance) || 0;
      const diff = (asc >= 400 || (rank >= 2 && asc >= 250)) ? 'Hard'
        : (asc >= 180 || km >= 6 || rank >= 2) ? 'Moderate' : 'Easy';
      facts.push([diff, window.t('trail.fact.difficulty')]);
    })();
    // The design's stat strip leads with a Match cell ("94% · Match · Rufus").
    // It's rendered here so it lives inside the same strip; paintMatch()
    // below fills it with the real score, or an honest create-profile
    // invitation for guests.
    factsEl.innerHTML =
      '<span class="f match" id="statMatch" hidden><a class="td2-match-link" id="statMatchLink" href="how-scoring-works.html"><b id="statMatchVal"></b><span id="statMatchSub"></span></a></span>'
      + facts.map(([val, label]) =>
        `<span class="f"><b>${val}</b><span>${label}</span></span>`).join('');
    const statMatch = document.getElementById('statMatch');
    const statMatchLink = document.getElementById('statMatchLink');
    const statMatchVal = document.getElementById('statMatchVal');
    const statMatchSub = document.getElementById('statMatchSub');

    // Personal match — needs a logged-in profile. Guests see the facts
    // plus an honest invitation: the score exists, it just isn't theirs yet.
    function paintMatchTeaser(){
      applyDetailRouteColor(safetyColor(t.safetyLevel));
      const actions = document.querySelector('.td-actions');
      if(actions) actions.classList.add('guest-actions');
      if(statMatch){
        statMatchVal.textContent = '?';
        statMatchSub.textContent = window.t('trail.matchCellTeaser');
        statMatchLink.href = '/?profile=1';
        statMatchLink.setAttribute('aria-label', window.t('trail.matchCellTeaser'));
        statMatch.hidden = false;
      }
      // Legacy slot retained for the main personalised match summary.
      const el = document.getElementById('trailMatch');
      if(el){ el.innerHTML = `<a href="/?profile=1">${window.t('trail.matchTeaser')}</a>`; el.hidden = false; }
    }
    function paintMatch(){
      if(typeof recommendTrail !== 'function') return;
      if(!window.DoloPawsAuth || !window.DoloPawsAuth.currentUser){
        paintMatchTeaser();
        return;
      }
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if(!profile){ paintMatchTeaser(); return; }
        const recommendation = recommendTrail(t, effectiveOverrides(profile, null));
        const n = recommendation.score;
        applyDetailRouteColor(detailRouteColorForScore(n));
        const actions = document.querySelector('.td-actions');
        if(actions) actions.classList.remove('guest-actions');
        const name = profile.name || window.t('trail.yourDog');
        if(statMatch){
          statMatchVal.innerHTML = (t.curated === false ? '≈' : '') + n + '<span class="pct">%</span>';
          statMatchSub.textContent = 'Match · ' + name;
          statMatchLink.href = 'how-scoring-works.html';
          statMatchLink.setAttribute('aria-label', `Learn how ORMA calculates the ${n}% trail match for ${name}`);
          statMatch.dataset.scoringVersion = recommendation.scoringVersion;
          statMatch.dataset.recommendationCategory = recommendation.category;
          statMatch.dataset.recommendationConfidence = recommendation.confidence;
          statMatch.hidden = false;
        }
        const el = document.getElementById('trailMatch');
        if(el){
          el.textContent = (t.curated === false ? '≈' : '') + n + '% ' +
            window.t('trail.matchFor', {name});
          el.dataset.scoringVersion = recommendation.scoringVersion;
          el.dataset.recommendationCategory = recommendation.category;
          el.dataset.recommendationConfidence = recommendation.confidence;
          el.hidden = false;
        }
      });
    }
    if(window.DoloPawsAuth) paintMatch();
    else window.addEventListener('dolopaws-auth-ready', paintMatch, { once: true });
    // Repaint when auth state resolves or changes, so a logged-in visitor
    // never keeps the guest teaser (and vice versa after logout).
    window.addEventListener('dolopaws-auth-changed', paintMatch);
  })();

  document.getElementById('trailDetailContent').innerHTML = renderTrailDetailContent(t);

  // "Good to know" — curated insights (history, geology, best practice)
  // with cited sources, for trails that have them in trails-data.js.
  if (Array.isArray(t.insights) && t.insights.length){
    const lang = (window.DoloPawsI18n && window.DoloPawsI18n.lang) || 'en';
    const box = document.createElement('div');
    box.style.cssText = 'margin-top:20px;';
    box.innerHTML = `<h2 style="font-size:18px;margin-bottom:10px;">${window.t('trail.insightsTitle')}</h2>` +
      t.insights.map(i => `
        <div style="background:var(--card);border:1px solid var(--paper-line);border-radius:12px;padding:12px 16px;margin-bottom:10px;font-size:13.5px;color:var(--ink);line-height:1.55;">
          ${(lang === 'it' && i.it) ? i.it : i.en}
          <div style="font-size:11.5px;color:var(--ink-soft);margin-top:6px;">${window.t('trail.source')}: ${i.url ? `<a href="${i.url}" target="_blank" rel="noopener">${i.source}</a>` : i.source}</div>
        </div>`).join('');
    const gtk = document.getElementById('goodToKnowBox');
    if (gtk){
      box.style.cssText = '';
      box.querySelector('h2').remove(); // card already has the heading
      gtk.appendChild(box);
    } else {
      const detail = document.getElementById('trailDetailContent');
      if (detail) detail.appendChild(box);
    }
  } else {
    // No hand-researched notes yet — fill the card with honest facts
    // derived from the route data itself, clearly labelled as such.
    const gtk = document.getElementById('goodToKnowBox');
    if (gtk){
      const facts = [];
      if (Array.isArray(t.elevationProfile) && t.elevationProfile.length){
        facts.push(window.t('gtk.autoAltitude', {m: Math.max(...t.elevationProfile.map(p => p.elev))}));
      }
      if (t.terrainType) facts.push(window.t('gtk.autoTerrain', {surface: t.terrainType}));
      const isLoopG = Array.isArray(t.path) && t.path.length > 1
        && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
      facts.push(isLoopG ? window.t('gtk.autoLoop', {d: t.distance}) : window.t('gtk.autoPointToPoint', {d: t.distance}));
      gtk.innerHTML = facts.map(f =>
        `<div style="border:1px solid var(--paper-line);border-radius:12px;padding:10px 14px;margin-bottom:8px;font-size:13px;color:var(--ink);line-height:1.55;">${f}</div>`).join('')
        + `<p style="font-size:11px;color:var(--ink-soft);margin:6px 0 0;">${window.t('gtk.autoNote')}</p>`;
    }
  }

  // Build turn-by-turn directions for trails stitched from more than one
  // numbered route, or a simpler start-only note for single-path loops
  // (a lake loop doesn't need "switch trails" instructions, but it still
  // deserves a clear "start here" pointer).
  if(Array.isArray(t.path) && ((Array.isArray(t.decisionPoints) && t.decisionPoints.length > 0) || t.startPoint)){
    const totalKm = t.distance;
    const firstStep = t.startPoint
      ? window.t('trail.dirStart', {label: trLabel(trustedStartLabel(t, t.startPoint.label))})
      : window.t('trail.dirStartAt', {name: (t.rifugi || []).find(r => r.km === 0)?.name || t.area});
    const steps = [firstStep];

    if(Array.isArray(t.decisionPoints) && t.decisionPoints.length > 0){
      // Merge rifugi and decision points that share a km value into one step,
      // rather than listing "pass X" and "switch trails at X" separately when
      // they're literally the same spot.
      const byKm = new Map();
      (t.rifugi || []).filter(r => r.km > 0).forEach(r => {
        byKm.set(r.km, [...(byKm.get(r.km) || []), { text: window.t('trail.dirPass', {name: r.name}), name: r.name }]);
      });
      t.decisionPoints.forEach(d => {
        const existing = byKm.get(d.km) || [];
        const instructionText = d.instruction.charAt(0).toLowerCase() + d.instruction.slice(1);
        // If a rifugio at this exact km is already named inside the decision
        // instruction, drop the separate "pass X" so the name isn't repeated.
        const deduped = existing.filter(e => !instructionText.toLowerCase().includes(e.name.toLowerCase()));
        byKm.set(d.km, [...deduped, { text: instructionText }]);
      });
      const events = [...byKm.entries()].sort((a, b) => a[0] - b[0]);
      events.forEach(([km, items]) => steps.push(`Km ${km}: ${items.map(i => i.text).join(window.t('trail.dirThen'))}.`));
    }

    steps.push(window.t('trail.dirEnd', {n: totalKm}));

    document.getElementById('trailDirections').innerHTML = steps.map(s => `<li>${s}</li>`).join('');
    document.getElementById('directionsWrap').hidden = false;
  }

  // Hike recording must not wait for the remote map engine or map tiles. QR
  // deep links initialise the GPS/readiness flow immediately; the map attaches
  // later when its normal lazy-load completes.
  const detailMapTarget = document.getElementById('trailMapBox') || document.getElementById('trailDetailMap');
  const hikeModeContainer = document.getElementById('trailDetailMap');
  const hikeModeController = typeof initHikeMode === 'function'
    ? initHikeMode(null, t, { container:hikeModeContainer })
    : null;

  // The detail map is expensive and sits below the trail summary. Load its
  // engine only as the map approaches the viewport (or a control is focused).
  const initDetailMap = () => {
  if(typeof maplibregl !== 'undefined' && typeof t.lat === 'number' && typeof t.lng === 'number'){
    const detailMapOptions = {
      container: 'trailDetailMap',
      style: 'https://tiles.openfreemap.org/styles/liberty',
      center: [t.lng, t.lat],
      zoom: 14,
      pitch: 0, // clean, flat, label-first by default — 3D is opt-in via the toggle
      attributionControl: { compact: true },
    };
    const map = new maplibregl.Map(window.DoloPawsMapRuntime
      ? window.DoloPawsMapRuntime.mapOptions(detailMapOptions) : detailMapOptions);
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
    window._dolopawsTrailMap = map; // debug/test handle
    initNearestTrailDirections(map, t);

    // Fullscreen map — manual ⤢ toggle, and automatic during hike mode.
    const mapBox = document.getElementById('trailMapBox');
    const expandBtn = document.getElementById('mapExpandBtn');
    const elevationPanel = document.getElementById('tdElevationPanel');
    const elevationHome = elevationPanel && elevationPanel.parentNode;
    function setMapFS(on){
      if(!mapBox) return;
      mapBox.classList.toggle('map-fs', on);
      document.body.classList.toggle('map-fs-open', on);
      if(elevationPanel && !elevationPanel.hidden){
        if(on) mapBox.appendChild(elevationPanel);
        else if(elevationHome) elevationHome.appendChild(elevationPanel);
      }
      if(expandBtn) expandBtn.innerHTML = on
        ? '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg> <span>Close map</span>'
        : '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg> <span>Expand map</span>';
      if(expandBtn) expandBtn.setAttribute('aria-label', on ? 'Close map' : 'Expand map');
      if(expandBtn) expandBtn.setAttribute('aria-expanded', String(on));
      setTimeout(() => map.resize(), 60);
    }
    window.DoloPawsMapFS = { enter: () => setMapFS(true), exit: () => setMapFS(false) };
    if(expandBtn) expandBtn.addEventListener('click', () => setMapFS(!mapBox.classList.contains('map-fs')));
    document.addEventListener('keydown', event => {
      if(event.key === 'Escape' && mapBox && mapBox.classList.contains('map-fs')) setMapFS(false);
    });
    // Live blue-dot location control — tap to see yourself on the map,
    // with heading arrow and follow-me tracking (Google Maps-style).
    map.addControl(new maplibregl.GeolocateControl({
      positionOptions: { enableHighAccuracy: true },
      trackUserLocation: true,
      showUserHeading: true,
      fitBoundsOptions: { maxZoom: 15.5 },
    }), 'top-right');

    // ---- Terrain / Satellite layer switch --------------------------------
    // Bound outside the 'load' handler so the buttons respond as soon as the
    // style is parsed, even while tiles are still streaming in on a slow
    // connection. The imagery slots in below the basemap's text labels, so
    // the route line, POIs and place names stay readable on top of it.
    const layerSwitch = document.getElementById('tdLayerSwitch');
    if (layerSwitch){
      const ensureSatelliteLayer = () => {
        if (map.getLayer('satellite-layer')) return true;
        if (!map.isStyleLoaded()) return false;
        map.addSource('satellite', {
          type: 'raster',
          tiles: ['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],
          tileSize: 256,
          maxzoom: 19,
          attribution: 'Imagery © Esri',
        });
        const firstSymbol = map.getStyle().layers.find(l => l.type === 'symbol');
        map.addLayer({
          id: 'satellite-layer',
          type: 'raster',
          source: 'satellite',
          layout: { visibility: 'none' },
          paint: { 'raster-resampling': 'linear', 'raster-fade-duration': 100 },
        }, firstSymbol && firstSymbol.id);
        return true;
      };
      layerSwitch.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-maplayer]');
        if (!btn || !ensureSatelliteLayer()) return;
        const sat = btn.getAttribute('data-maplayer') === 'satellite';
        map.setLayoutProperty('satellite-layer', 'visibility', sat ? 'visible' : 'none');
        // The vector style's building fills sit above the raster and would
        // paint every roof grey over the photo imagery — hide them on
        // satellite.
        map.getStyle().layers.forEach(layer => {
          if(layer['source-layer'] === 'building' || /building/i.test(layer.id)){
            try { map.setLayoutProperty(layer.id, 'visibility', sat ? 'none' : 'visible'); } catch(err){}
          }
        });
        // Base buttons only — the 3D toggle keeps its own pressed state.
        layerSwitch.querySelectorAll('[data-maplayer]').forEach(b => {
          const on = b === btn;
          b.classList.toggle('on', on);
          b.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
      });
    }

    map.on('load', async () => {
      if(hikeModeController && hikeModeController.attachMap) hikeModeController.attachMap(map);
      if(window.DoloPawsMapRuntime) window.DoloPawsMapRuntime.enhance(map);
      const attribution = document.querySelector('#trailDetailMap .maplibregl-ctrl-attrib');
      if(attribution){
        attribution.classList.add('maplibregl-compact');
        attribution.classList.remove('maplibregl-compact-show');
        const toggle = attribution.querySelector('.maplibregl-ctrl-attrib-button');
        if(toggle) toggle.setAttribute('aria-expanded', 'false');
      }
      let liftsVisible = false;        // Lifts are optional planning context
      // Everyday trail context is visible immediately; only optional planning
      // overlays remain in Layers.
      const poiStates = { fountains: true, huts: true, food: true, places: true, veterinary: false };
      const amenityMarkers = [];       // { marker, group } for curated fallbacks
      if(window.DoloPawsIcons) await window.DoloPawsIcons.registerMapImages(map);
      const setLayerChipLabel = (button, iconKey, label) => {
        if(!button) return;
        button.innerHTML = window.DoloPawsIcons
          ? window.DoloPawsIcons.chipHtml(iconKey, label)
          : label;
      };
      setLayerChipLabel(document.getElementById('routesToggle'), 'routes', 'Trail routes');
      setLayerChipLabel(document.getElementById('liftsToggle'), 'lifts', 'Lift stations');
      setLayerChipLabel(document.getElementById('veterinaryToggle'), 'veterinary', 'Veterinary clinics');
      setLayerChipLabel(document.getElementById('nearbyToggle'), 'nearby', 'Nearby trails');
      addTerrainSource(map);
      increaseLabelDensity(map);
      addTerrainToggle(map, 'trailDetailMap', 1.5, 45,
        document.querySelector('#tdLayerSwitch [data-map3d]'));
      const loadSecondaryPois = () => {
        renderAllLifts(map, { visible: liftsVisible });
        if (typeof initDetailPois === 'function') initDetailPois(map, t);
      };
      if(window.DoloPawsMapRuntime) window.DoloPawsMapRuntime.onIdle(loadSecondaryPois, 1400);
      else setTimeout(loadSecondaryPois, 900);

      // ---- Layers dropdown -------------------------------------------------
      // Match the main map: one compact control with independent route and
      // POI categories, instead of a tall stack of unrelated buttons.
      const layersBtn = document.getElementById('detailLayersBtn');
      const layersPanel = document.getElementById('detailLayersPanel');
      if(layersBtn && layersPanel){
        layersBtn.addEventListener('click', event => {
          event.stopPropagation();
          const open = layersPanel.style.display === 'flex';
          layersPanel.style.display = open ? 'none' : 'flex';
          layersBtn.textContent = open ? 'Layers' : 'Close ✕';
          layersBtn.setAttribute('aria-expanded', String(!open));
        });
        layersPanel.addEventListener('click', event => event.stopPropagation());
        document.addEventListener('click', () => {
          layersPanel.style.display = 'none';
          layersBtn.textContent = 'Layers';
          layersBtn.setAttribute('aria-expanded', 'false');
        });
      }

      const POI_SOURCES = {
        fountains: ['detail-water'],
        huts: ['detail-huts'],
        food: ['detail-bars'],
        places: ['detail-places'],
      };
      const POI_SUFFIXES = ['-layer', '-layer-lowzoom', '-cluster', '-cluster-count'];
      function applyPoiVisibility(group){
        const visible = poiStates[group];
        (POI_SOURCES[group] || []).forEach(source => POI_SUFFIXES.forEach(suffix => {
          const id = source + suffix;
          if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visible ? 'visible' : 'none');
        }));
        amenityMarkers.filter(item => item.group === group).forEach(item => {
          item.marker.getElement().style.display = visible ? '' : 'none';
        });
      }
      // Veterinary facilities are fetched only when requested: the nearest
      // options can sit well beyond the route viewport and do not need to
      // compete with the trail during ordinary map use.
      const veterinaryButton = document.getElementById('veterinaryToggle');
      let veterinaryResults = null;
      let veterinaryLoad = null;
      if(veterinaryButton){
        veterinaryButton.addEventListener('click', async () => {
          const care = window.ORMA_VeterinaryCare;
          if(!care) return;
          poiStates.veterinary = !poiStates.veterinary;
          veterinaryButton.classList.toggle('on', poiStates.veterinary);
          veterinaryButton.setAttribute('aria-pressed', String(poiStates.veterinary));
          if(!poiStates.veterinary){
            care.setVisible(map, false);
            return;
          }
          if(veterinaryResults){
            care.setVisible(map, true);
            care.focusFacilities(map, t, veterinaryResults);
            return;
          }
          veterinaryButton.disabled = true;
          setLayerChipLabel(veterinaryButton, 'veterinary', 'Finding veterinary clinics…');
          try{
            veterinaryLoad = veterinaryLoad || care.loadMapLayer(map, t);
            veterinaryResults = await veterinaryLoad;
            if(!veterinaryResults.length){
              poiStates.veterinary = false;
              veterinaryButton.classList.remove('on');
              veterinaryButton.setAttribute('aria-pressed', 'false');
              setLayerChipLabel(veterinaryButton, 'veterinary', 'No veterinary clinics mapped nearby');
              return;
            }
            setLayerChipLabel(veterinaryButton, 'veterinary', `Veterinary clinics (${veterinaryResults.length})`);
            care.setVisible(map, poiStates.veterinary);
            if(poiStates.veterinary) care.focusFacilities(map, t, veterinaryResults);
          }catch(error){
            veterinaryLoad = null;
            poiStates.veterinary = false;
            veterinaryButton.classList.remove('on');
            veterinaryButton.setAttribute('aria-pressed', 'false');
            setLayerChipLabel(veterinaryButton, 'veterinary', 'Veterinary clinics unavailable');
          }finally{
            veterinaryButton.disabled = false;
          }
        });
      }
      // detail-pois.js adds its layers asynchronously (after a fetch), so
      // reapply whenever a POI source finishes loading.
      map.on('sourcedata', (e) => {
        if(!e.sourceId || !e.isSourceLoaded) return;
        Object.keys(POI_SOURCES).forEach(group => {
          if(POI_SOURCES[group].includes(e.sourceId)) applyPoiVisibility(group);
        });
      });

      // ---- Lifts toggle -------------------------------------------------
      // Lift lines and stations start hidden, then remain available as an
      // explicit planning layer. The state also applies if the deferred lift
      // data finishes loading after the customer has pressed the control.
      function applyLiftVisibility(){
        const visibility = liftsVisible ? 'visible' : 'none';
        ['detail-gondolas-line', 'detail-gondola-stations-layer'].forEach(id => {
          if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visibility);
        });
      }
      const liftsToggleBtn = document.getElementById('liftsToggle');
      if(liftsToggleBtn){
        liftsToggleBtn.addEventListener('click', () => {
          liftsVisible = !liftsVisible;
          liftsToggleBtn.classList.toggle('on', liftsVisible);
          liftsToggleBtn.setAttribute('aria-pressed', liftsVisible ? 'true' : 'false');
          applyLiftVisibility();
        });
      }


      // Waymarked Trails' own public hiking overlay — same underlying OSM
      // data as our base map, but with their dedicated trail-route styling
      // (numbered routes, waymarking) that a general basemap doesn't draw.
      //
      // IMPORTANT: adding a layer with no target position stacks it on top
      // of EVERYTHING in the base style, including all its text labels —
      // that's what was actually causing the "hard to read" problem, in
      // both 3D and flat mode. Finding the first text/label layer and
      // inserting before it keeps the overlay above roads/fills but below
      // every place name, so labels stay legible either way.
      const firstLabelLayer = map.getStyle().layers.find(l => l.type === 'symbol');
      map.addSource('waymarked-hiking', {
        type: 'raster',
        tiles: ['https://tile.waymarkedtrails.org/hiking/{z}/{x}/{y}.png'],
        tileSize: 256,
        attribution: '© Sarah Hoffmann (CC-BY-SA) — waymarkedtrails.org',
      });
      map.addLayer({
        id: 'waymarked-hiking-layer',
        type: 'raster',
        source: 'waymarked-hiking',
        // VISIBLE by default: the waymark network is how walkable ground
        // around the route stays discoverable. "Marked routes" un-ticks it
        // for anyone who wants the clean basemap.
        layout: { visibility: 'visible' },
        // Match the homepage treatment: the public network should read as
        // quiet grey context while its red/white/black route shields retain a
        // trace of colour. At detail-page zooms the same raster is deliberately
        // more opaque and higher contrast so its existing trail numbers remain
        // readable; no duplicate number layer is drawn over the map. Linear
        // resampling removes the blocky, pixelated edges that nearest-neighbour
        // scaling caused at close trail zooms.
        // This raster remains above the wider ORMA match-colour line, leaving
        // that green/amber/red line visible as the selected route's underlay.
        paint: {
          'raster-opacity': [
            'interpolate', ['linear'], ['zoom'],
            7, 0.10,
            10, 0.14,
            12, 0.20,
            14, 0.64,
            16, 0.92,
          ],
          'raster-saturation': -0.90,
          'raster-contrast': 0.38,
          'raster-resampling': 'linear',
          'raster-fade-duration': 120,
        },
      }, firstLabelLayer ? firstLabelLayer.id : undefined);
      if (typeof addBaseHillshade === 'function') addBaseHillshade(map, 'waymarked-hiking-layer');
      const routesToggleBtn = document.getElementById('routesToggle');
      if (routesToggleBtn){
        routesToggleBtn.classList.add('on');
        routesToggleBtn.setAttribute('aria-pressed', 'true');
        routesToggleBtn.addEventListener('click', () => {
          const showing = routesToggleBtn.classList.toggle('on');
          routesToggleBtn.setAttribute('aria-pressed', showing ? 'true' : 'false');
          if (map.getLayer('waymarked-hiking-layer')) {
            map.setLayoutProperty('waymarked-hiking-layer', 'visibility', showing ? 'visible' : 'none');
          }
        });
      }

      // ---- Other trails' routes — browse and switch without going back ----
      // Every other trail with a real GPS route renders as a secondary line;
      // clicking one pops up its name and a link straight to its page. Added
      // BEFORE the main route's layers so the current trail always draws on
      // top of its neighbours.
      const nearbyTrails = nearbyTrailCandidates(t, typeof trails !== 'undefined' ? trails : []);
      const otherTrails = nearbyTrails.map(item => item.trail);
      const nearbyToggleBtn = document.getElementById('nearbyToggle');
      if(nearbyToggleBtn){
        nearbyToggleBtn.hidden = nearbyTrails.length === 0;
        if(nearbyTrails.length){
          setLayerChipLabel(nearbyToggleBtn, 'nearby', `Nearby trails (${nearbyTrails.length})`);
        }
      }
      if(otherTrails.length){
        map.addSource('other-trails', {
          type: 'geojson',
          data: {
            type: 'FeatureCollection',
            features: otherTrails.map(x => ({
              type: 'Feature',
              properties: { id: x.id, name: x.name, safetyLevel: x.safetyLevel, distance: x.distance },
              geometry: { type: 'LineString', coordinates: x.path.map(([lat, lng]) => [lng, lat]) },
            })),
          },
        });
        map.addLayer({
          id: 'other-trails-line',
          type: 'line',
          source: 'other-trails',
          minzoom: 9,
          layout: { visibility: 'none', 'line-join': 'round', 'line-cap': 'round' },
          paint: {
            'line-color': '#858D88',
            'line-width': 3.5,
            'line-opacity': 0.52,
            'line-dasharray': [1.5, 1.25],
          },
        }, 'waymarked-hiking-layer');
        // Wide invisible twin so the thin neighbour lines are easy to hit.
        map.addLayer({
          id: 'other-trails-hit',
          type: 'line',
          source: 'other-trails',
          minzoom: 9,
          layout: { visibility: 'none', 'line-join': 'round', 'line-cap': 'round' },
          paint: { 'line-color': '#000', 'line-width': 16, 'line-opacity': 0.01 },
        }, 'waymarked-hiking-layer');
        map.addSource('nearby-trail-points', {
          type: 'geojson',
          data: {
            type: 'FeatureCollection',
            features: nearbyTrails.map(item => ({
              type: 'Feature',
              properties: {
                id: item.trail.id,
                name: item.trail.name,
                safetyLevel: item.trail.safetyLevel,
                distance: item.trail.distance,
                awayKm: Math.round(item.distanceKm * 10) / 10,
              },
              geometry: { type: 'Point', coordinates: [item.mapPoint[1], item.mapPoint[0]] },
            })),
          },
        });
        map.addLayer({
          id: 'nearby-trail-points-circle',
          type: 'circle',
          source: 'nearby-trail-points',
          layout: { visibility: 'none' },
          paint: {
            'circle-radius': 6,
            'circle-color': '#929A95',
            'circle-stroke-color': '#ffffff',
            'circle-stroke-width': 2,
          },
        });
        map.addLayer({
          id: 'nearby-trail-points-label',
          type: 'symbol',
          source: 'nearby-trail-points',
          minzoom: 8,
          layout: {
            visibility: 'none',
            'text-field': ['get', 'name'],
            'text-size': 11,
            'text-font': ['Noto Sans Regular'],
            'text-offset': [0, 1.25],
            'text-anchor': 'top',
          },
          paint: {
            'text-color': '#59615C',
            'text-halo-color': '#ffffff',
            'text-halo-width': 2,
          },
        });
        const escName = s => String(s == null ? '' : s).replace(/[&<>"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));
        const openNearbyPopup = (e) => {
          // If this click also lands on the current trail's own route,
          // let the main route win — no neighbour popup on top of it.
          if(e.type === 'click' && e.features && e.features[0] && e.features[0].geometry.type === 'LineString' && map.getLayer('single-trail-path-line')){
            const onMain = map.queryRenderedFeatures(e.point, { layers: ['single-trail-path-line'] });
            if(onMain.length) return;
          }
          const f = e.features && e.features[0];
          if(!f) return;
          const p = f.properties;
          new maplibregl.Popup({ offset: 12, maxWidth: '260px' })
            .setLngLat(e.lngLat)
            .setHTML(
              `<div style="font:700 14px 'Bricolage Grotesque',sans-serif;color:#2E4034;">${escName(p.name)}</div>` +
              `<div style="font:600 11.5px 'Inter',sans-serif;color:#6B7A6E;margin-top:3px;">${escName(String(p.distance))} km trail${p.awayKm != null ? ` · ${escName(String(p.awayKm))} km away` : ''}</div>` +
              `<a href="trail.html?id=${encodeURIComponent(p.id)}" style="display:inline-block;margin-top:9px;font:700 12.5px 'Inter',sans-serif;color:#fff;background:#2E4034;padding:8px 14px;border-radius:9px;text-decoration:none;">Open this trail →</a>`
            )
            .addTo(map);
        };
        map.on('click', 'other-trails-hit', openNearbyPopup);
        map.on('click', 'nearby-trail-points-circle', openNearbyPopup);
        map.on('mouseenter', 'other-trails-hit', () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', 'other-trails-hit', () => { map.getCanvas().style.cursor = ''; });
        map.on('mouseenter', 'nearby-trail-points-circle', () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', 'nearby-trail-points-circle', () => { map.getCanvas().style.cursor = ''; });

        if(nearbyToggleBtn){
          let showingNearbyOverview = false;
          nearbyToggleBtn.addEventListener('click', () => {
            showingNearbyOverview = !showingNearbyOverview;
            nearbyToggleBtn.classList.toggle('on', showingNearbyOverview);
            nearbyToggleBtn.setAttribute('aria-pressed', showingNearbyOverview ? 'true' : 'false');
            ['other-trails-line', 'other-trails-hit', 'nearby-trail-points-circle', 'nearby-trail-points-label'].forEach(id => {
              if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', showingNearbyOverview ? 'visible' : 'none');
            });
            const bounds = new maplibregl.LngLatBounds();
            t.path.forEach(([lat, lng]) => bounds.extend([lng, lat]));
            if(showingNearbyOverview){
              otherTrails.forEach(trail => trail.path.forEach(([lat, lng]) => bounds.extend([lng, lat])));
              setLayerChipLabel(nearbyToggleBtn, 'routes', 'Focus this trail');
              map.fitBounds(bounds, { padding: 54, maxZoom: 13 });
            } else {
              setLayerChipLabel(nearbyToggleBtn, 'nearby', `Nearby trails (${nearbyTrails.length})`);
              map.fitBounds(bounds, { padding: 60, maxZoom: 17 });
            }
          });
        }
      }

      if(Array.isArray(t.path) && t.path.length > 1){
        const selectedRouteColor = window._dolopawsTrailRouteColor || safetyColor(t.safetyLevel);
        map.addSource('single-trail-path', {
          type: 'geojson',
          data: {
            type: 'Feature',
            properties: {},
            geometry: { type: 'LineString', coordinates: t.path.map(([lat, lng]) => [lng, lat]) },
          },
        });
        // Keep the route above the hiking-network raster so its visible colour
        // always communicates this dog's match. Labels remain above the route.
        map.addLayer({
          id: 'single-trail-path-casing',
          type: 'line',
          source: 'single-trail-path',
          layout: { 'line-join': 'round', 'line-cap': 'round' },
          paint: { 'line-color': '#FFFDF7', 'line-width': 17, 'line-opacity': 0.96 },
        }, firstLabelLayer ? firstLabelLayer.id : undefined);
        map.addLayer({
          id: 'single-trail-path-line',
          type: 'line',
          source: 'single-trail-path',
          layout: { 'line-join': 'round', 'line-cap': 'round' },
          paint: { 'line-color': selectedRouteColor, 'line-width': 13, 'line-opacity': 1 },
        }, firstLabelLayer ? firstLabelLayer.id : undefined);

        // Closed loops are intentionally direction-neutral: hikers can join
        // anywhere and walk clockwise or anticlockwise. Keep arrows only for
        // routes whose start and end are genuinely different.
        const routeIsLoop = distMeters(t.path[0], t.path[t.path.length - 1]) <= 75;
        if(!routeIsLoop){
          map.addLayer({
            id: 'single-trail-direction-arrows',
            type: 'symbol',
            source: 'single-trail-path',
            layout: {
              'symbol-placement': 'line',
              'symbol-spacing': 70,
              'text-field': '➤',
              'text-size': 18,
              'text-rotation-alignment': 'map',
              'text-keep-upright': false,
              'text-allow-overlap': true,
              'text-ignore-placement': true,
            },
            paint: {
              'text-color': '#ffffff',
              'text-halo-color': selectedRouteColor,
              'text-halo-width': 2,
            },
          });
        }
        // Put the trail's known references on the ORMA route itself. The
        // public hiking raster sits below the thick match-colour line, so its
        // baked-in numbers can otherwise disappear beneath the selected path.
        const routeRefFeatures = window.DoloPawsTrailRouteRefs
          ? window.DoloPawsTrailRouteRefs.featuresForTrail(t)
          : [];
        if(routeRefFeatures.length){
          map.addSource('single-trail-route-refs', {
            type:'geojson',
            data:{ type:'FeatureCollection', features:routeRefFeatures },
          });
          window.DoloPawsTrailRouteRefs.addShieldLayer(map, {
            id:'single-trail-route-number',
            source:'single-trail-route-refs',
            beforeId:firstLabelLayer && firstLabelLayer.id,
          });
        }
        const bounds = new maplibregl.LngLatBounds();
        t.path.forEach(([lat, lng]) => bounds.extend([lng, lat]));
        map.fitBounds(bounds, { padding: 60, maxZoom: 17 });

        setupElevationProfile(map, t);

        // NOTE: curated rifugi/water emoji markers used to be placed here
        // from the trail's km data — removed: they duplicated the real OSM
        // amenity dots (detail-pois.js), showing two markers for the same
        // rifugio. The OSM dot layers are now the single amenity language
        // on every map; the curated km list still renders as text in the
        // "Trail details" column. Emoji markers remain only for things OSM
        // can't know: recommended start, decision points, community flags.

        // Decision points — where a hiker needs to switch from one numbered
        // route onto another. Always real, verified coordinates (these come
        // from actual confirmed junctions between two GPX tracks, never
        // interpolated) so no fallback branch is needed here.
        (t.decisionPoints || []).forEach(d => {
          new maplibregl.Marker({ element: makeIconEl('switch', '#D6A038'), offset: [14, -14] })
            .setLngLat([d.lng, d.lat])
            .setPopup(new maplibregl.Popup({ offset: 16 }).setHTML(`<b>Km ${d.km}</b><br>${d.instruction}`))
            .addTo(map);
        });

        // Only draw a trail-owned waypoint when it has verified GPS
        // coordinates. Interpolating from a rounded kilometre can put an icon
        // on the wrong bend or side of a loop. OSM-backed points already render
        // at their source coordinates through detail-pois.js, so do not draw a
        // duplicate marker on top of them here.
        if(Array.isArray(t.path) && t.path.length > 1){
          const addWaypoint = (waypoint, icon, label) => {
            if(!waypoint || waypoint.osmId || typeof waypoint.lat !== 'number' || typeof waypoint.lng !== 'number') return;
            const mk = new maplibregl.Marker({ element: makeIconEl(icon), offset: [0, -6] })
              .setLngLat([waypoint.lng, waypoint.lat])
              .setPopup(new maplibregl.Popup({ offset: 14 }).setHTML(`<b>${itinEsc(label)}</b>${typeof waypoint.km === 'number' ? `<br>Km ${waypoint.km}` : ''}`))
              .addTo(map);
            amenityMarkers.push({ marker: mk, group: icon === 'hut' ? 'huts' : 'fountains' });
            mk.getElement().style.display = poiStates[icon === 'hut' ? 'huts' : 'fountains'] ? '' : 'none';
          };
          (t.rifugi || []).forEach(r => addWaypoint(r, 'hut', trLabel(r.name)));
          (t.waterSources || []).forEach(w => {
            addWaypoint(w, 'water', trLabel(trustedWaterLabel(t, w.label)));
          });
        }

        // Recommended starting point — a loop can technically be walked
        // from anywhere on it, but a real, well-marked access/parking point
        // is worth calling out explicitly rather than leaving people to
        // guess where to begin.
        if(t.startPoint){
          new maplibregl.Marker({ element: makeIconEl('start', '#2E4034'), offset: [-14, -14] })
            .setLngLat([t.startPoint.lng, t.startPoint.lat])
            .setPopup(new maplibregl.Popup({ offset: 16 }).setHTML(`<b>${trLabel(trustedStartLabel(t, t.startPoint.label))}</b>`))
            .addTo(map);
        }
      } else {
        new maplibregl.Marker({ color: '#6FA8BE' }).setLngLat([t.lng, t.lat]).addTo(map);
      }

      if (typeof makeBasemapPoisClickable === 'function') makeBasemapPoisClickable(map);

      // Community dog-safety flags — list, map markers, report modal.
      if (typeof initTrailReports === 'function') initTrailReports(map, t);
    });
  }
  };
  if(window.DoloPawsMapRuntime){
    const mobileMapLoadBtn = document.getElementById('mobileMapLoadBtn');
    const deferMobileMap = !!(window.matchMedia && window.matchMedia('(max-width: 700px)').matches && !hikeDeepLinkRequested);
    let detailMapSchedule;
    if(deferMobileMap){
      let mapStartPromise = null;
      detailMapTarget.dataset.mapState = 'waiting';
      const startMobileMap = () => {
        if(mapStartPromise) return mapStartPromise;
        detailMapTarget.dataset.mapState = 'loading';
        if(mobileMapLoadBtn) mobileMapLoadBtn.hidden = true;
        mapStartPromise = window.DoloPawsMapRuntime.load()
          .then(initDetailMap)
          .then(result => {
            detailMapTarget.dataset.mapState = 'ready';
            return result;
          })
          .catch(error => {
            detailMapTarget.dataset.mapState = 'error';
            detailMapTarget.setAttribute('aria-label', 'Map unavailable. Trail details remain available below.');
            console.error('ORMA map failed to initialise:', error);
            return null;
          });
        return mapStartPromise;
      };
      detailMapSchedule = { start:startMobileMap, get promise(){ return mapStartPromise; } };
      if(mobileMapLoadBtn) mobileMapLoadBtn.addEventListener('click', startMobileMap, { once:true });
      // Once the document itself has finished, prepare the map in idle time.
      // A direct tap always wins and starts it immediately.
      window.addEventListener('load', () => {
        if(typeof requestIdleCallback === 'function') requestIdleCallback(startMobileMap, { timeout:8000 });
        else setTimeout(startMobileMap, 4000);
      }, { once:true });
    }else{
      detailMapSchedule = window.DoloPawsMapRuntime.whenVisible(detailMapTarget, initDetailMap, {
        rootMargin:'360px 0px',
        triggers:[document.getElementById('mapExpandBtn')],
      });
    }
    const expand = document.getElementById('mapExpandBtn');
    if(expand){
      expand.addEventListener('click', async event => {
        if(window._dolopawsTrailMap || !detailMapSchedule || !detailMapSchedule.start) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        await detailMapSchedule.start();
        if(window._dolopawsTrailMap) expand.click();
      }, { capture:true });
    }
    // Let the map prepare in the background for hike guidance, but do not
    // block the readiness sheet or GPS recording on that network work.
    if(hikeDeepLinkRequested && detailMapSchedule && detailMapSchedule.start){
      detailMapSchedule.start();
    }
  } else {
    initDetailMap();
  }

  // Save button — reflects and updates real account state, same pattern as the trail cards.
  const saveBtn = document.getElementById('detailSaveBtn');
  let saveStatusTimer = null;
  function showSaveStatus(message){
    let status = document.getElementById('detailSaveStatus');
    if(!status){
      status = document.createElement('div');
      status.id = 'detailSaveStatus';
      status.className = 'dw-toast';
      status.setAttribute('role', 'status');
      status.setAttribute('aria-live', 'polite');
      document.body.appendChild(status);
    }
    if(saveStatusTimer) clearTimeout(saveStatusTimer);
    status.textContent = message;
    status.hidden = false;
    status.className = 'dw-toast dw-toast--in';
    saveStatusTimer = setTimeout(() => {
      status.hidden = true;
      status.className = 'dw-toast';
    }, 4200);
  }
  function paintSaveBtn(isFav){
    const heart = isFav
      ? '<svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 21S3.5 14.6 3.5 8.8A4.8 4.8 0 0 1 12 6a4.8 4.8 0 0 1 8.5 2.8C20.5 14.6 12 21 12 21z"/></svg>'
      : '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20.4S4.2 14.5 4.2 9.2A4.3 4.3 0 0 1 12 6.6a4.3 4.3 0 0 1 7.8 2.6c0 5.3-7.8 11.2-7.8 11.2z"/></svg>';
    saveBtn.innerHTML = heart + (isFav ? ' Saved' : ' Save');
    saveBtn.classList.toggle('saved', isFav);
  }
  async function handleSaveAuth(user){
    if(!user || !window.DoloPawsAuth){
      saveBtn.onclick = () => {
        if(window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('save');
      };
      paintSaveBtn(false);
      return;
    }
    const favorites = await window.DoloPawsAuth.getFavorites();
    if(window.DoloPawsTrailAction && window.DoloPawsTrailAction.consume('save') && !favorites[t.id]){
      favorites[t.id] = true;
      const saved = await window.DoloPawsAuth.setFavorites(favorites);
      if(saved) showSaveStatus(window.t('save.added'));
      else {
        delete favorites[t.id];
        showSaveStatus(window.t('save.error'));
      }
    }
    paintSaveBtn(!!favorites[t.id]);
    saveBtn.onclick = async () => {
      saveBtn.disabled = true;
      const current = await window.DoloPawsAuth.getFavorites();
      const wasSaved = !!current[t.id];
      if(wasSaved) delete current[t.id]; else current[t.id] = true;
      const saved = await window.DoloPawsAuth.setFavorites(current);
      if(saved){
        paintSaveBtn(!wasSaved);
        showSaveStatus(window.t(wasSaved ? 'save.removed' : 'save.added'));
      } else {
        paintSaveBtn(wasSaved);
        showSaveStatus(window.t('save.error'));
      }
      saveBtn.disabled = false;
    };
  }
  window.addEventListener('dolopaws-auth-changed', e => handleSaveAuth(e.detail.user));
  if(window.DoloPawsAuth) handleSaveAuth(window.DoloPawsAuth.currentUser);

  // GPX export is intentionally account-gated. The file contains the ordered
  // route and trailhead, but not the richer safety context shown on ORMA.
  const exportGpxBtn = document.getElementById('exportGpxBtn');
  if(exportGpxBtn){
    let exportStatusTimer = null;
    function showExportStatus(message){
      let status = document.getElementById('exportGpxStatus');
      if(!status){
        status = document.createElement('div');
        status.id = 'exportGpxStatus';
        status.className = 'dw-toast';
        status.setAttribute('role', 'status');
        status.setAttribute('aria-live', 'polite');
        document.body.appendChild(status);
      }
      if(exportStatusTimer) clearTimeout(exportStatusTimer);
      status.textContent = message;
      status.hidden = false;
      status.className = 'dw-toast dw-toast--in';
      exportStatusTimer = setTimeout(() => {
        status.hidden = true;
        status.className = 'dw-toast';
      }, 5200);
    }
    function runGpxExport(){
      if(!window.DoloPawsGpxExport){
        showExportStatus('GPX export could not load. Please refresh and try again.');
        return false;
      }
      try {
        window.DoloPawsGpxExport.download(t);
        showExportStatus('GPX downloaded. It contains the route only — check ORMA for safety context.');
        return true;
      } catch(error){
        showExportStatus(error && error.message
          ? error.message : 'This trail could not be exported.');
        return false;
      }
    }
    function handleExportAuth(user){
      exportGpxBtn.onclick = () => {
        if(!(user && window.DoloPawsAuth)){
          if(window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('export-gpx');
          return;
        }
        runGpxExport();
      };
      if(user && window.DoloPawsTrailAction
        && window.DoloPawsTrailAction.consume('export-gpx')){
        runGpxExport();
      }
    }
    window.addEventListener('dolopaws-auth-changed', event => handleExportAuth(event.detail.user));
    handleExportAuth(window.DoloPawsAuth && window.DoloPawsAuth.currentUser);
  }
}

// This file is deferred, so the trail DOM and synchronous regional payload
// are available even if authentication is still delaying DOMContentLoaded.
if(document.querySelector('.td2')){
  init();
} else if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
;

// ---- trail-blueprint.js ----
/**
 * trail-blueprint.js — the "answer-first" layer of the trail page.
 *
 * Fills the new blueprint sections WITHOUT touching trail.js logic:
 *   - Verified/Imported seal in the hero
 *   - Answer strip: "Right for your dog?" · "Today?" · "Getting there"
 *   - Nearby trails (same valley, via regions-config)
 *
 * Everything is derived from data that already exists (trail fields,
 * the live weather chip trail.js populates, the same scoreTrail() the
 * hero match uses). Nothing is invented. Load AFTER trail.js.
 */
(function () {
  'use strict';

  const params = new URLSearchParams(window.location.search);
  const trailId = params.get('id');
  const t = (typeof trails !== 'undefined') ? trails.find(x => x.id === trailId) : null;
  if (!t) return;

  const $ = (id) => document.getElementById(id);
  const trust = window.DoloPawsTrailTrust;
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const cardCopy = (s) => String(s == null ? '' : s)
    .trim()
    .replace(/\s*(?:—|--)+\s*/g, '. ')
    .replace(/\.\s*\./g, '.')
    .replace(/\s{2,}/g, ' ')
    .replace(/(^|[.!?]\s+)([a-z])/g, (match, lead, letter) => lead + letter.toUpperCase());
  const dpIcon = (key, size = 14) => window.DoloPawsIcons
    ? window.DoloPawsIcons.renderIconSvg(key, { mode:'inline', color:'currentColor', size })
    : '';
  const tt = (key, vars, fallback) => {
    const out = (typeof window.t === 'function') ? window.t(key, vars) : null;
    return (out && out !== key) ? out : fallback;
  };
  const accessTarget = (() => {
    const start = t.startPoint || {};
    const lat = typeof start.lat === 'number' ? start.lat : t.lat;
    const lng = typeof start.lng === 'number' ? start.lng : t.lng;
    return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
  })();
  const wireTrailheadDirections = (element, statusElement) => {
    if(!element || !accessTarget) return;
    element.removeAttribute('target');
    element.removeAttribute('rel');
    element.href = '#';
    element.addEventListener('click', async event => {
      event.preventDefault();
      const access = window.DoloPawsTrailAccess;
      if(!access){
        if(statusElement) statusElement.textContent = 'Directions are unavailable right now.';
        return;
      }
      element.setAttribute('aria-disabled', 'true');
      if(statusElement) statusElement.textContent = 'Checking your distance from the trailhead…';
      try{
        const plan = await access.planFromCurrent(navigator, accessTarget, navigator.userAgent, 100);
        if(!plan.allowed){
          if(statusElement) statusElement.textContent =
            `Directions are available when you are within 100 km of the trail (${Math.round(plan.distanceKm)} km away).`;
          return;
        }
        if(statusElement) statusElement.textContent = `${Math.round(plan.distanceKm)} km away · opening directions…`;
        window.open(plan.url, '_blank', 'noopener');
      }catch(error){
        if(statusElement) statusElement.textContent =
          'Allow location access to check that you are within 100 km of this trail.';
      }finally{
        element.removeAttribute('aria-disabled');
      }
    });
  };

  /* ---- Tier seal in the hero ------------------------------------- */
  (function seal() {
    const el = $('verifiedSeal');
    if (!el) return;
    const style = trust && trust.tierBadgeStyle ? trust.tierBadgeStyle(t) : (t.curated === false ? 'imported' : 'verified');
    const label = trust ? trust.provenanceLabel(t) : (t.curated === false ? 'Imported trail' : 'Verified by ORMA');
    // Render the same pill the browse-trail cards use, not a bespoke inline seal.
    el.innerHTML = (window.DoloPawsIcons && window.DoloPawsIcons.badgeHtml)
      ? window.DoloPawsIcons.badgeHtml(style, label)
      : dpIcon(style) + '<span>' + esc(label) + '</span>';
    el.hidden = false;
  })();

  /* ---- Public review record --------------------------------------
     Claim-level evidence remains in the Trail Verification Desk. */
  (function reviewRecord() {
    const meta = $('trailReviewMeta');
    if (!meta) return;
    const graduation = trust && trust.graduationProgress ? trust.graduationProgress(t) : null;
    const progress = trust && trust.reviewProgress ? trust.reviewProgress(t) : null;
    if (graduation) {
      const date = trust.formatReviewDate(t.reviewedAt || (t.verified && t.verified.date));
      meta.textContent = graduation.verified
        ? `Verified by ORMA on ${date}. Check current conditions before setting out.`
        : 'This mapped trail has not yet been field-verified by ORMA. Check local access rules and current conditions before setting out.';
    } else if (progress) {
      meta.textContent = progress.checked === progress.total
        ? 'Trail details have been reviewed by ORMA. Check current conditions before setting out.'
        : 'This mapped trail has not yet been field-verified by ORMA. Check local access rules and current conditions before setting out.';
    } else if (t.routeAudit && t.reviewedAt) {
      const date = trust ? trust.formatReviewDate(t.reviewedAt) : t.reviewedAt;
      meta.textContent = `Route details reviewed by ORMA on ${date}. Check current conditions before setting out.`;
    } else {
      meta.textContent = t.curated === false
        ? 'This mapped trail has not yet been field-verified by ORMA. Check local access rules and current conditions before setting out.'
        : 'Trail information prepared by ORMA. Check current conditions before setting out.';
    }
  })();

  /* ---- Answer strip ---------------------------------------------- */
  const strip = $('qaStrip');
  // The personalised match below now carries the decision context, so these
  // older answer cards stay out of the visual flow.
  if (strip) strip.hidden = true;

  // Card 1 — Right for your dog? Three honest states.
  function paintDogCard() {
    const title = $('qaDogTitle'), sub = $('qaDogSub');
    if (!title || !sub) return;

    const factBits = [];
    if (t.safetyLevel) {
      const baseRisk = safetyLabel(t.safetyLevel);
      factBits.push((trust ? trust.riskLabel(t, baseRisk) : baseRisk).toLowerCase());
    }
    if (typeof t.distance === 'number') factBits.push(t.distance <= 6 ? 'easy distance' : `${t.distance} km`);
    if (typeof t.shadeCoverage === 'number') factBits.push(t.shadeCoverage >= 40 ? 'good shade' : 'little shade');
    const factLine = factBits.join(' · ');

    function guest() {
      title.textContent = tt('qa.dogGuest', null, 'Would this suit your dog?');
      const returnToTrail = encodeURIComponent(location.pathname.split('/').pop() + location.search);
      sub.innerHTML = esc(factLine) + (factLine ? ' · ' : '') +
        '<a href="account.html?next=' + returnToTrail + '">' + tt('qa.dogGuestCta', null, 'create a free profile to find out') + ' →</a>';
    }
    function noProfile() {
      title.textContent = tt('qa.dogNoProfile', null, 'Whose paws are we scoring?');
      const returnToTrail = encodeURIComponent(location.pathname.split('/').pop() + location.search);
      sub.innerHTML = '<a href="account.html?next=' + returnToTrail + '">' + tt('qa.dogNoProfileCta', null, 'Add your dog, 2 minutes') + ' →</a>';
    }
    function paint() {
      if (typeof scoreTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) { guest(); return; }
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) { noProfile(); return; }
        const n = scoreTrail(t, (typeof effectiveOverrides === 'function') ? effectiveOverrides(profile, null) : profile);
        const name = profile.name || tt('trail.yourDog', null, 'your dog');
        const approx = t.curated === false ? '≈' : '';
        title.textContent = tt('qa.dogScored', { n: approx + n, name },
          `Right for ${name}? ${approx}${n}%`);
        sub.textContent = factLine;
      }).catch(guest);
    }
    if (window.DoloPawsAuth) paint();
    else window.addEventListener('dolopaws-auth-ready', paint, { once: true });
    window.addEventListener('dolopaws-auth-changed', paint);
  }
  paintDogCard();

  // Card 3 — Getting there. Start point label + directions link.
  (function paintAccessCard() {
    const card = $('qaAccess'), title = $('qaAccessTitle'), sub = $('qaAccessSub');
    if (!card) return;
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    if (typeof lat !== 'number') return;
    title.textContent = tt('qa.accessTitle', null, 'Getting there');
    const rawLabel = sp.label || tt('trail.itinParkFallback', null, 'Trailhead');
    const label = esc(trust ? trust.startPointLabel(t, rawLabel) : rawLabel);
    sub.innerHTML = label +
      ` · <a href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}" target="_blank" rel="noopener">` +
      tt('trail.openMaps', null, 'get directions') + ' →</a>';
    card.hidden = false;
  })();

  /* ---- Nearby trails (same valley first, then same region) ------- */
  (function nearby() {
    const wrapEl = $('nearbyTrails'), grid = $('nearbyGrid');
    if (!wrapEl || !grid || typeof trails === 'undefined') return;
    const pool = trails.filter(o => o.id !== t.id);
    const sameValley = pool.filter(o => o.valley && o.valley === t.valley);
    const sameRegion = pool.filter(o => o.region === t.region && o.valley !== t.valley);
    const picks = sameValley.slice(0, 4);
    for (const o of sameRegion) { if (picks.length >= 4) break; picks.push(o); }
    if (!picks.length) return;
    // Reference gallery card: photo, floating match % chip, serif name, meta.
    const cardPhoto = source => ({
      'images/lago-di-braies.webp':'images/lago-di-braies-480.webp',
      'images/lago-di-carezza.webp':'images/lago-di-carezza-480.webp',
      'images/boucle-du-marais-des-chassettes.webp':'images/boucle-du-marais-des-chassettes-480.webp',
      'images/circuit-beatrice-de-savoie.webp':'images/circuit-beatrice-de-savoie-480.webp',
      'images/itineraire-decouverte-de-la-nature.webp':'images/itineraire-decouverte-de-la-nature-480.webp',
    }[source] || source);
    grid.innerHTML = picks.map(o => `
      <a class="near-card" href="trail.html?id=${encodeURIComponent(o.id)}" data-near-id="${esc(o.id)}">
        <div class="ph"${o.imageIcon ? ` style="background-image:url('${esc(cardPhoto(o.imageIcon))}');"` : ''}><span class="pct near-pct" hidden></span></div>
        <div class="bd">
          <div class="nm">${esc(o.name)}</div>
          <div class="mt">${esc(o.valley || o.area || '')} · ${o.distance} km · ${esc(trust ? trust.riskLabel(o, safetyLabel(o.safetyLevel)) : safetyLabel(o.safetyLevel))}</div>
        </div>
      </a>`).join('');
    wrapEl.hidden = false;
    const seeAll = $('nearbySeeAll');
    if (seeAll && (t.valley || t.area)) seeAll.textContent = 'See all in ' + (t.valley || t.area) + ' \u2192';

    // Personalise: retitle the section and fill each pick's real match %
    // chip — same scoreTrail() as everywhere else.
    function personalise() {
      if (typeof scoreTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) return;
        const heading = $('nearbyTitle');
        if (heading && profile.name) heading.textContent = 'Nearby trails, ranked for ' + profile.name;
        const ov = (typeof effectiveOverrides === 'function') ? effectiveOverrides(profile, null) : profile;
        for (const o of picks) {
          const slot = grid.querySelector(`[data-near-id="${CSS.escape(o.id)}"] .near-pct`);
          if (!slot) continue;
          slot.textContent = (o.curated === false ? '≈' : '') + scoreTrail(o, ov) + '%';
          slot.hidden = false;
        }
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) personalise();
    else window.addEventListener('dolopaws-auth-ready', personalise, { once: true });
    window.addEventListener('dolopaws-auth-changed', personalise);
  })();

  /* ---- Dog tips note (verified trails only) ----------------------- */
  (function tipsNote() {
    const note = $('dogTipsNote');
    if (note && t.curated !== false && t.tips) note.hidden = false;
  })();

  /* ---- Decision-first hero and safety dashboard ------------------ */
  (function decisionFlow() {
    // Hero photo behind the title (reference: dimmed photo + cream veil).
    const heroPhoto = $('tdHeroPhoto');
    if (heroPhoto && t.imageIcon && heroPhoto.tagName !== 'IMG') {
      const stem = String(t.imageIcon).replace(/\.webp$/, '');
      const wideSources = [
        'images/boucle-du-marais-des-chassettes.webp',
        'images/circuit-beatrice-de-savoie.webp',
        'images/itineraire-decouverte-de-la-nature.webp',
      ];
      const background = wideSources.includes(t.imageIcon)
        ? `${stem}-${window.matchMedia('(max-width: 700px)').matches ? '960' : '1280'}.webp`
        : t.imageIcon;
      heroPhoto.style.backgroundImage = `url("${background.replace(/["')]/g, '')}")`;
    }

    // Breadcrumb: "← Trails · {region} · {valley}"
    const crumb = $('tdBreadcrumb');
    if (crumb && /^browse-trails\.html(?:[?#]|$)/.test(crumb.getAttribute('href') || '')) {
      const regionName = t.region === 'savoy' ? 'Savoy' : 'Dolomites';
      crumb.textContent = '← Trails · ' + regionName + (t.valley ? ' · ' + t.valley : '');
    }

    // Safety rating as the same coloured pill the browse cards use.
    const riskLine = $('tdRiskLine');
    if (riskLine && t.safetyLevel) {
      const labels = { 'low-risk': 'Low-risk terrain', 'moderate': 'Moderate terrain', 'caution': 'Caution terrain' };
      const baseRisk = labels[t.safetyLevel] || '';
      const riskText = trust ? trust.riskLabel(t, baseRisk) : baseRisk;
      riskLine.innerHTML = (window.DoloPawsIcons && window.DoloPawsIcons.badgeHtml)
        ? window.DoloPawsIcons.badgeHtml(t.safetyLevel, riskText)
        : esc(riskText);
      riskLine.hidden = false;
    }

    // Elevation figures under the real chart; hide the block honestly
    // when the trail has no profile data.
    const prof = Array.isArray(t.elevationProfile) ? t.elevationProfile.map(p => Number(p.elev) || 0) : [];
    if (prof.length > 1) {
      const figs = $('tdElevFigs');
      if (figs) {
        $('tdElevStart').textContent = prof[0].toLocaleString() + ' m';
        $('tdElevHigh').textContent = Math.max(...prof).toLocaleString() + ' m';
        $('tdElevClimb').textContent = '+' + (t.elevation != null ? t.elevation : Math.max(...prof) - Math.min(...prof)) + ' m';
        figs.hidden = false;
      }
    } else {
      const h = $('tdElevH'), svg = $('elevProf');
      if (h) h.hidden = true;
      if (svg) svg.style.display = 'none';
    }

    const easyTerrain = Number(t.terrainRank) === 0;
    const lowRisk = t.safetyLevel === 'low-risk';
    const verdict = t.curated === false
      ? 'Automated estimate from mapped route data. Exposure, shade, livestock and current conditions are not field verified.'
      : lowRisk && easyTerrain
      ? 'A gentle, low-risk choice for most dogs.'
      : t.safetyLevel === 'caution'
        ? 'A more demanding trail: check the hazards and your dog’s confidence before committing.'
        : 'A manageable trail for prepared dogs; review the route constraints before committing.';
    const heroVerdict = $('heroVerdict');
    if (heroVerdict) heroVerdict.textContent = verdict;

    const svg = (kind) => {
      const paths = {
        paw: '<circle cx="8" cy="8.2" r="1.6" fill="#5DCAA5"/><circle cx="12" cy="6.6" r="1.6" fill="#5DCAA5"/><circle cx="16" cy="8.2" r="1.6" fill="#5DCAA5"/><path d="M8.4 16.5c0-2.4 1.5-4.2 3.6-4.2s3.6 1.8 3.6 4.2c0 1.4-1.1 2.5-2.5 2.5-.7 0-1.1-.3-1.7-.7-.5.4-1 .7-1.7.7-1.3 0-2.3-1.1-2.3-2.5Z" fill="#1D9E75"/>',
        shade: '<path d="M12 5v14M7 19h10M6 12c0-3 2.7-6 6-6s6 3 6 6Z" fill="none" stroke="#4A7856" stroke-width="1.8"/><path d="m7 12-3 3M17 12l3 3" fill="none" stroke="#4A7856" stroke-width="1.8"/>',
        water: '<path d="M12 4c2.8 3.4 4.5 6 4.5 8.4a4.5 4.5 0 1 1-9 0C7.5 10 9.2 7.4 12 4Z" fill="#378ADD"/>',
        heat: '<circle cx="12" cy="12" r="4" fill="#D6A038"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4" fill="none" stroke="#D6A038" stroke-width="1.8" stroke-linecap="round"/>',
        park: '<rect x="4.5" y="4.5" width="15" height="15" rx="3.5" fill="#fff" stroke="#4C87C6" stroke-width="1.6"/><path d="M10 16.2V7.8h3.1a2.6 2.6 0 0 1 0 5.2H10" fill="none" stroke="#4C87C6" stroke-width="1.9" stroke-linecap="round"/>',
        route: '<path d="M6 18c2-5 5.5-9 12-12" fill="none" stroke="#2C5C34" stroke-width="2" stroke-linecap="round"/><circle cx="7" cy="18" r="1.7" fill="#2C5C34"/><path d="M17.5 4.2l2.6 1-1 2.5-2.6-1z" fill="#E24B4A"/>',
        crowd: '<ellipse cx="5" cy="8" rx="2.5" ry="4.5" fill="#8B6F47" transform="rotate(-20 5 8)"/><ellipse cx="19" cy="8" rx="2.5" ry="4.5" fill="#8B6F47" transform="rotate(20 19 8)"/><circle cx="12" cy="14" r="7" fill="#8B6F47"/><ellipse cx="12" cy="16" rx="4" ry="3" fill="#A08060"/><circle cx="9.5" cy="12" r="1.2" fill="#3D2817"/><circle cx="9.8" cy="11.5" r="0.4" fill="#fff"/><circle cx="14.5" cy="12" r="1.2" fill="#3D2817"/><circle cx="14.8" cy="11.5" r="0.4" fill="#fff"/><circle cx="12" cy="16" r="1" fill="#3D2817"/><path d="M12 17 Q11 18 10 17.5" fill="none" stroke="#3D2817" stroke-width="0.8" stroke-linecap="round"/><path d="M12 17 Q13 18 14 17.5" fill="none" stroke="#3D2817" stroke-width="0.8" stroke-linecap="round"/>',
        mountain: '<path d="m4 18 6-10 3 5 2-3 5 8Z" fill="none" stroke="#BA7517" stroke-width="1.8" stroke-linejoin="round"/>',
        loop: '<path d="M18 8a7 7 0 1 0 1 7M18 4v4h-4" fill="none" stroke="#3E7A91" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>'
      };
      return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[kind]}</svg>`;
    };
    const signalEl = $('matchSignals');
    const isLoop = Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
    const climb = Number(t.elevation) || 0;
    const signalData = [
      ['paw', easyTerrain ? 'Gentle paw surface' : 'Mixed paw surface', easyTerrain ? 'Flat or packed underfoot based on route information' : (t.terrainType || 'Check pads at breaks')],
      ['route', 'Route effort', `${t.distance} km${climb ? ` · +${climb} m` : ''}`],
      ['loop', isLoop ? 'Loop route' : 'One-way route', isLoop ? 'Returns to the starting point' : 'Plan the return journey']
    ];
    if (signalEl) {
      signalEl.innerHTML = signalData.map(([icon, title, sub]) =>
        `<div class="match-signal"><span class="mark" aria-hidden="true">✦</span><span><b>${esc(title)}</b><small>${esc(sub)}</small></span></div>`).join('');
    }
    // "Why this fits {name}" heading follows the profile when one exists.
    function paintWhyTitle() {
      if (!window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(p => {
        if (p && p.name && $('tdWhyTitle')) $('tdWhyTitle').textContent = 'Why this fits ' + p.name;
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) paintWhyTitle();
    else window.addEventListener('dolopaws-auth-ready', paintWhyTitle, { once: true });

    // Assessment note ABOVE the box, below the heading
    const assessmentNote = $('assessmentNote');
    if (assessmentNote) {
      assessmentNote.innerHTML = trust ? trust.assessmentNote(t) : `<strong style="color: var(--ink);">Our assessment of this trail:</strong> route facts are weighed against your dog's profile. Current conditions can still change.`;
    }

    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const startBtn = $('startNavigationBtn');
    if (startBtn) {
      startBtn.addEventListener('click', (event) => {
        const mapStart = $('mapStartHikeBtn');
        if (!mapStart) return;
        event.preventDefault();
        mapStart.click();
      });
    }
    const directionsBtn = $('getDirectionsBtn');
    wireTrailheadDirections(directionsBtn, $('getDirectionsStatus'));

    // Share popover (reference): Copy link with inline "✓ Link copied",
    // Message a walking buddy (sms:), Email this trail (mailto:).
    const shareBtn = $('detailShareBtn');
    const sharePop = $('tdSharePop');
    if (shareBtn && sharePop) {
      const smsLink = $('tdShareSms'), mailLink = $('tdShareMail');
      const shareDetails = () => {
        const url = new URL(location.pathname, location.href);
        url.searchParams.set('id', t.id);
        const activeTab = new URLSearchParams(location.search).get('tab');
        if (/^(?:safety|reviews)$/.test(activeTab || '')) url.searchParams.set('tab', activeTab);
        const shareUrl = url.href;
        return {
          url: shareUrl,
          text: t.name + ' on ORMA: ' + shareUrl
        };
      };
      const closeShare = () => {
        sharePop.hidden = true;
        shareBtn.setAttribute('aria-expanded', 'false');
      };
      const updateShareLinks = () => {
        const details = shareDetails();
        if (smsLink) smsLink.href = 'sms:?body=' + encodeURIComponent(details.text);
        if (mailLink) mailLink.href = 'mailto:?subject=' + encodeURIComponent(t.name + ' | ORMA') + '&body=' + encodeURIComponent(details.text);
      };
      shareBtn.addEventListener('click', () => {
        sharePop.hidden = !sharePop.hidden;
        shareBtn.setAttribute('aria-expanded', sharePop.hidden ? 'false' : 'true');
        if (!sharePop.hidden) updateShareLinks();
      });
      document.addEventListener('click', (e) => {
        if (!sharePop.hidden && !sharePop.contains(e.target) && e.target !== shareBtn && !shareBtn.contains(e.target)) {
          closeShare();
        }
      });
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !sharePop.hidden) {
          closeShare();
          shareBtn.focus();
        }
      });
      const copyBtn = $('tdCopyLink');
      if (copyBtn) copyBtn.addEventListener('click', async () => {
        const shareUrl = shareDetails().url;
        try {
          await navigator.clipboard.writeText(shareUrl);
          copyBtn.textContent = '✓ Link copied';
          copyBtn.style.color = '#2f5138';
          setTimeout(() => {
            copyBtn.textContent = 'Copy link';
            copyBtn.style.color = '';
            closeShare();
          }, 1400);
        } catch (e) {
          window.prompt(tt('trail.copyLink', null, 'Copy this link'), shareUrl);
        }
      });
    }

    const aboutFacts = $('aboutFacts');
    if (false && aboutFacts) {
      const facts = [
        ['paw', 'Comfortable underpaw', easyTerrain ? 'Paved and packed-gravel surfaces' : (t.terrainType || 'Mixed trail')],
        ['water', hasWater ? 'Water at the trailhead' : 'Bring water', hasWater ? 'Fill up before joining the route' : 'No source is listed on this route'],
        ['loop', 'Loop route', Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200 ? `${t.distance} km, back to the same parking area` : 'Check your return transport'],
        ['mountain', `${Math.max(...(t.elevationProfile || [{ elev: 0 }]).map(p => p.elev))} m altitude`, 'Mountain weather can change quickly'],
      ];
      aboutFacts.innerHTML = facts.map(([icon, title, sub]) => `<div class="about-fact">${svg(icon)}<span><b>${esc(title)}</b><small>${esc(sub)}</small></span></div>`).join('');
      
      // Add loop callout if it's a loop
      const isLoop = Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
      if (isLoop && $('loopCallout')) {
        if ($('loopCallout')) {
        $('loopCallout').innerHTML = `<div class="loop-callout" style="display: flex; gap: 8px; align-items: center; padding: 8px 10px; background: var(--sage-dim); border-radius: 8px; margin-bottom: 16px; border-left: 3px solid var(--success); font-size: 11px;">
          <svg style="width: 14px; height: 14px; flex: none; color: var(--success);" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M18 8a7 7 0 1 0 1 7M18 4v4h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          <div style="color: var(--ink);"><b style="display: block; line-height: 1.2;">Loop</b><span style="color: var(--ink-soft); font-size: 10px;">${t.distance} km</span></div>
        </div>`;
      }
      }
    }

    const avatar = $('matchDogAvatar');
    const matchTitle = $('personalMatchTitle');
    const matchSummary = $('matchSummary');
    const personalScore = $('personalScore');
    const fallbackPaw = svg('paw');
    if (avatar) avatar.innerHTML = fallbackPaw;
    function paintPersonalMatch() {
      if (typeof recommendTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) return;
        const name = profile.name || 'your dog';
        const recommendation = recommendTrail(
          t,
          typeof effectiveOverrides === 'function' ? effectiveOverrides(profile, null) : profile
        );
        const score = recommendation.score;
        // Reference action card: 96px conic ring (#4a7c59 on #e6e0cf track),
        // "MATCH FOR {NAME}" kicker, breed line underneath.
        if (personalScore) {
          const ringColor = score >= 70 ? '#4a7c59' : score >= 50 ? '#c98a3e' : '#b2542e';
          personalScore.innerHTML =
            `<div class="td-ring" style="background:conic-gradient(${ringColor} ${Math.round((score / 100) * 360)}deg,#e6e0cf 0);">` +
            `<div class="td-ring-in">${t.curated === false ? '≈' : ''}${score}%</div></div>`;
          personalScore.dataset.scoringVersion = recommendation.scoringVersion;
          personalScore.dataset.recommendationCategory = recommendation.category;
          personalScore.dataset.recommendationConfidence = recommendation.confidence;
          personalScore.hidden = false;
        }
        const label = $('tdMatchLabel');
        if (label) {
          $('tdMatchName').textContent = 'MATCH FOR ' + name.toUpperCase();
          $('tdMatchBreed').textContent = profile.breed || '';
          label.hidden = false;
        }
        if (matchTitle) matchTitle.textContent = `Match for ${name}`;
        if (matchSummary) {
          const category = {
            'strong-option': 'Strong option',
            'possible-with-cautions': 'Possible with cautions',
            'not-recommended': 'Not recommended',
          }[recommendation.category] || 'Personal recommendation';
          matchSummary.textContent = `${category} · ${recommendation.confidence} confidence`;
          matchSummary.dataset.scoringVersion = recommendation.scoringVersion;
        }
        if (avatar && profile.photo) avatar.innerHTML = `<img src="${esc(profile.photo)}" alt="${esc(name)}">`;
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) paintPersonalMatch();
    else window.addEventListener('dolopaws-auth-ready', paintPersonalMatch, { once: true });
    window.addEventListener('dolopaws-auth-changed', paintPersonalMatch);

    // Trail description inside the white box
    const descEl = $('matchDescription');
    if (descEl && t.desc) {
      descEl.textContent = cardCopy(t.desc);
    }
    
    // In-page tabs: Overview / Dog safety / Reviews & photos.
    const tabsNav = $('trailTabsNav');
    if (tabsNav) {
      const panelIds = ['tabOverview', 'tabSafety', 'tabReviews'];
      const tabNames = {
        tabOverview: 'overview',
        tabSafety: 'safety',
        tabReviews: 'reviews'
      };
      const activateTab = (btn, historyMode) => {
        tabsNav.querySelectorAll('[data-tab]').forEach(b => {
          const on = b === btn;
          b.classList.toggle('active', on);
          b.setAttribute('aria-selected', on ? 'true' : 'false');
        });
        panelIds.forEach(id => {
          const panel = $(id);
          if (panel) panel.hidden = id !== btn.dataset.tab;
        });
        if (historyMode && window.history) {
          const url = new URL(window.location.href);
          const tabName = tabNames[btn.dataset.tab];
          if (tabName === 'overview') url.searchParams.delete('tab');
          else if (tabName) url.searchParams.set('tab', tabName);
          const target = url.pathname + url.search + url.hash;
          if (target !== window.location.pathname + window.location.search + window.location.hash) {
            if (historyMode === 'push') window.history.pushState({}, '', target);
            else window.history.replaceState({}, '', target);
          }
        }
      };

      tabsNav.querySelectorAll('[data-tab]').forEach(btn => {
        btn.addEventListener('click', () => activateTab(btn, 'push'));
      });

      const requestedTab = new URLSearchParams(window.location.search).get('tab');
      const requestedPanel = Object.keys(tabNames).find(id => tabNames[id] === requestedTab);
      const initialTab = requestedPanel
        ? tabsNav.querySelector('[data-tab="' + requestedPanel + '"]')
        : tabsNav.querySelector('[data-tab].active') || tabsNav.querySelector('[data-tab]');
      if (initialTab) activateTab(initialTab, false);
      window.addEventListener('popstate', () => {
        const tabName = new URLSearchParams(window.location.search).get('tab') || 'overview';
        const panelId = Object.keys(tabNames).find(id => tabNames[id] === tabName) || 'tabOverview';
        const tab = tabsNav.querySelector('[data-tab="' + panelId + '"]');
        if (tab) activateTab(tab, false);
      });
    }
  })();

  /* ---- Dog safety tab: Good/Caution rows from real trail fields ---- */
  (function safetyRows() {
    const box = $('dogSafetyRows');
    if (!box) return;
    const text = `${t.tips || ''} ${t.desc || ''} ${(t.surfaceHazards || []).join(' ')}`.toLowerCase();
    const hasWater = Array.isArray(t.waterSources) && t.waterSources.length > 0;
    const shade = typeof t.shadeCoverage === 'number' ? t.shadeCoverage : null;
    const maxAlt = Math.max(0, ...(t.elevationProfile || []).map(p => Number(p.elev) || 0));
    const rows = [];
    const caution = (title, sub, guideId) => rows.push({ title, sub, guideId });
    const addAssessment = (item, guideId) => {
      if (!item || item.ok) return;
      caution(item.title, item.detail, guideId);
    };

    addAssessment(trust ? trust.exposureAssessment(t) : (t.exposure
      ? { ok: false, title: 'Exposure', detail: 'Narrow ledges or unprotected drop-offs occur on parts of the route.' }
      : null), 'exposure');
    addAssessment(trust ? trust.livestockAssessment(t, text) : null, 'livestock');
    addAssessment(trust ? trust.surfaceAssessment(t) : (Number(t.terrainRank) !== 0
      ? { ok: false, title: 'Surface hazards', detail: (t.terrainType || 'Gravel and mixed rock') + '. Check pads at breaks; consider booties for tender paws.' }
      : null), 'paws');
    addAssessment(trust ? trust.heatAssessment(t) : null, 'heat');
    addAssessment(trust ? trust.waterAssessment(t) : (hasWater
      ? { ok: true, title: 'Water', detail: 'A water source is mapped on this route. Bring a bowl.' }
      : { ok: false, title: 'Water', detail: 'No water source is mapped. Carry enough for the dog.' }), 'water');
    if (maxAlt >= 1800) caution('Season & altitude', `Tops out around ${maxAlt} m. Snow lingers into early summer and weather turns quickly.`, 'altitude');

    if (!rows.length) {
      box.innerHTML = '<p class="safety-clear">No additional route cautions are highlighted. Continue to check live weather and local signs.</p>';
      return;
    }
    const rowMarkup = r => `
      <div class="safety-row is-caution"${r.guideId ? ` data-guide-id="${esc(r.guideId)}"` : ''}>
        <span class="pill">Caution</span>
        <span class="safety-row-copy"><b>${esc(r.title)}</b><small>${esc(r.sub)}</small></span>
      </div>`;
    box.innerHTML = rows.map(rowMarkup).join('');
  })();

  /* ---- Getting there + getting around — keep travel to the trailhead
     separate from the numbered waymarks used once the walk begins. ----- */
  (function parking() {
    const card = $('td2ParkingCard'), grid = $('td2ParkingGrid'), maps = $('td2MapsLink');
    const aroundCard = $('td2GettingAroundCard'), aroundGrid = $('td2GettingAroundGrid');
    if (!card || !grid || !aroundCard || !aroundGrid) return;
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const pin = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#2E4034" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-7-5.5-7-11a7 7 0 0 1 14 0c0 5.5-7 11-7 11z"></path><circle cx="12" cy="10" r="2.5"></circle></svg>';
    const routeRefs = window.DoloPawsTrailRouteRefs
      ? window.DoloPawsTrailRouteRefs.forTrail(t)
      : [];
    const startLabel = cardCopy(sp.label || t.valley || t.area || 'the marked trailhead')
      .replace(/^Start here[.:\s-]*/i, '');
    const routeSequence = routeRefs.join(' → ');
    const hasSectionOnlyRefs = Array.isArray(t.routeRefSegments) && t.routeRefSegments.length > 0;
    const routeSwitches = window.DoloPawsTrailRouteRefs
      ? window.DoloPawsTrailRouteRefs.switchesForTrail(t)
      : [];
    const verifiedRouteGuidance = t.routeNumberGuidance && typeof t.routeNumberGuidance === 'object'
      ? t.routeNumberGuidance
      : null;
    const routeOverview = cardCopy(String(t.desc || '').split(/\n\s*\n/)[0] || '');
    const guidanceIsLandmarkLed = verifiedRouteGuidance && verifiedRouteGuidance.mode === 'landmarks';
    const guidanceSourceLinks = verifiedRouteGuidance && Array.isArray(verifiedRouteGuidance.sources)
      ? verifiedRouteGuidance.sources.filter(source => source && /^https:\/\//.test(source.url || '')).map(source =>
          `<a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.label || source.authority || 'Official route guide')} ↗</a>`
        ).join(' · ')
      : '';
    const routeBadges = routeRefs.length
      ? `<div class="td2-route-ref-list" aria-label="Trail numbers in order">${routeRefs.map((ref, index) =>
          `${index ? '<span class="td2-route-ref-arrow" aria-hidden="true">→</span>' : ''}<span class="td2-route-ref">${esc(ref)}</span>`
        ).join('')}</div>`
      : '';
    const switchGuidance = routeSwitches.length
      ? `<ol class="td2-route-switch-list">
          <li>Begin the hike on trail <b>${esc(routeSwitches[0].from)}</b>.</li>
          ${routeSwitches.map(item => {
            const atKm = item.km == null ? 'At the mapped junction' : `At approximately km ${esc(item.km.toFixed(1).replace(/\.0$/, ''))}`;
            const nearby = (Array.isArray(t.rifugi) ? t.rifugi : []).find(place =>
              Number.isFinite(Number(place && place.km)) && item.km != null && Math.abs(Number(place.km) - item.km) <= 0.15);
            return `<li>${atKm}${nearby ? `, near ${esc(nearby.name)}` : ''}, switch from trail <b>${esc(item.from)}</b> to trail <b>${esc(item.to)}</b>.</li>`;
          }).join('')}
          <li>Stay on trail <b>${esc(routeSwitches[routeSwitches.length - 1].to)}</b> for the final section to the route finish.</li>
        </ol>`
      : '';
    const routeRefMarkup = verifiedRouteGuidance
      ? `<div class="s"><p><b>Start:</b> ${esc(verifiedRouteGuidance.start)}</p><p><b>${guidanceIsLandmarkLed ? 'Route' : 'Trail numbers and route'}:</b> ${esc(verifiedRouteGuidance.sequence)}</p><p><b>${guidanceIsLandmarkLed ? 'Key turns' : 'Where to switch'}:</b> ${esc(verifiedRouteGuidance.switches)}</p>${guidanceSourceLinks ? `<p class="td2-route-sources">${guidanceSourceLinks}</p>` : ''}</div>`
      : routeRefs.length
      ? `${routeBadges}${switchGuidance || `<div class="s">${hasSectionOnlyRefs
          ? `${routeRefs.length === 1 ? 'Trail' : 'Trails'} ${esc(routeSequence)} ${routeRefs.length === 1 ? 'is' : 'are'} marked only on the verified section${routeRefs.length === 1 ? '' : 's'} shown on the map. Follow the mapped ORMA line for the full route and confirm destination names at junctions.`
          : routeRefs.length === 1
            ? `Follow waymarked trail <b>${esc(routeRefs[0])}</b> along the mapped hike. No change to another numbered trail is recorded in the current route source; confirm destination names at junctions.`
            : `This hike uses trails ${esc(routeSequence)}, but the exact numbered switch point${routeRefs.length > 2 ? 's are' : ' is'} still awaiting verification. Follow the mapped ORMA line and local destination signs; do not rely on the number sequence alone.`}</div>`}`
      : routeOverview
        ? `<div class="s"><p><b>Route overview:</b> ${esc(routeOverview)}</p></div>`
        : '';
    const routeCard = {
      ic:'',
      t:verifiedRouteGuidance ? 'How to follow this route' : (routeSwitches.length ? 'Waymarked trail numbers and switches' : (routeRefs.length ? 'Waymarked trail numbers' : 'Route overview')),
      s:routeRefMarkup,
      routeRefs:true,
    };
    const renderCards = cards => cards.map(c => `<div class="td2-park${c.routeRefs ? ' td2-route-refs' : ''}"><span class="ic">${c.ic}</span><div><div class="t">${esc(c.t)}</div>${c.routeRefs ? c.s : `<div class="s">${c.s}</div>`}</div></div>`).join('');
    aroundGrid.innerHTML = routeRefMarkup ? renderCards([routeCard]) : '';
    aroundCard.hidden = !routeRefMarkup;
    if (typeof lat !== 'number' || typeof lng !== 'number') {
      grid.innerHTML = renderCards([{
        ic:pin,
        t:'Recommended starting point',
        s:'Trailhead directions are not yet available for this route.',
      }]);
      if (maps) maps.hidden = true;
      card.hidden = false;
      return;
    }
    const cards = [{
      ic:pin,
      t:'Recommended starting point',
      s:`Head to ${esc(startLabel)}. Use the directions link to navigate to the route start.`,
    }];
    grid.innerHTML = renderCards(cards);
    if (maps) maps.hidden = false;
    wireTrailheadDirections(maps, $('td2MapsStatus'));
    card.hidden = false;
  })();

  /* ---- Sticky sidebar: today's conditions + walking forecast --------
     Reference markup, real Open-Meteo data at the trailhead. ---------- */
  (function sidebar() {
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const condCard = $('tdConditions'), fcCard = $('sideForecast'), fcDays = $('tdForecastDays');
    const publishWeather = detail => {
      window.DoloPawsWeatherSnapshot = detail;
      window.dispatchEvent(new CustomEvent('dolopaws-weather-ready', { detail }));
    };
    if (typeof lat !== 'number') {
      publishWeather({ status: 'unavailable', capturedAt: Date.now() });
      return;
    }

    const valleyEl = $('sideFcValley');
    if (valleyEl) valleyEl.textContent = (t.valley || t.area) ? '· ' + (t.valley || t.area) : '';

    const WMO = (c) => c === 0 ? 'Clear' : c <= 2 ? 'Mostly clear' : c === 3 ? 'Overcast'
      : c <= 48 ? 'Fog' : c <= 57 ? 'Drizzle' : c <= 67 ? 'Rain' : c <= 77 ? 'Snow'
      : c <= 82 ? 'Showers' : c <= 86 ? 'Snow showers' : 'Thunderstorms';

    // Prototype weather glyphs: a sun for clear/mostly-clear, a cloud otherwise.
    const SUN = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#E8A93A" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4.2" fill="#F7C96B" stroke="none"></circle><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5 5l1.4 1.4M17.6 17.6L19 19M19 5l-1.4 1.4M6.4 17.6L5 19"></path></svg>';
    const CLOUD = '<svg width="18" height="16" viewBox="0 0 24 24" fill="#B7C6C9"><path d="M7 18h10a4 4 0 0 0 .5-7.97A5.5 5.5 0 0 0 6.5 9 4 4 0 0 0 7 18z"></path></svg>';
    const iconFor = (code) => code <= 2 ? SUN : CLOUD;
    // Paw-safety badge from the day's high (same thresholds as the score's heat rules).
    const dayBadge = (hi) => hi >= 22 ? { t: 'Heat', bg: '#F5E4C6', fg: '#8A5A16' } : { t: 'Good', bg: '#E4EADF', fg: '#2C5C34' };

    fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&current=temperature_2m,weathercode&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max,sunrise,sunset&hourly=temperature_2m&forecast_days=6&timezone=auto`)
      .then(r => r.json())
      .then(d => {
        if (!d || !d.daily) {
          publishWeather({ status: 'unavailable', capturedAt: Date.now() });
          return;
        }
        publishWeather({
          status: 'ready',
          capturedAt: Date.now(),
          temperatureC: d.current && d.current.temperature_2m,
          trailId: t.id,
        });
        // ---- Today's conditions card ----
        if (d.current) {
          const cur = Math.round(d.current.temperature_2m);
          const tempEl = $('tdCondTemp');
          if (tempEl) tempEl.textContent = cur + '°C';
          const paw = cur >= 28 ? { t: 'Caution', bg: '#F3D9D2', fg: '#9C3A25' }
            : cur >= 22 ? { t: 'Warm', bg: '#F5E4C6', fg: '#8A5A16' }
            : { t: 'Good', bg: '#E4EADF', fg: '#2C5C34' };
          const pawEl = $('tdCondPaw');
          if (pawEl) { pawEl.textContent = paw.t; pawEl.style.background = paw.bg; pawEl.style.color = paw.fg; }
          const win = window.DoloPawsWeatherWindow
            ? window.DoloPawsWeatherWindow.recommendation({
              currentTime:d.current.time,
              durationHours:t.hours,
              dailyDates:d.daily.time,
              sunrises:d.daily.sunrise,
              sunsets:d.daily.sunset,
              hourlyTimes:d.hourly && d.hourly.time,
              hourlyTemps:d.hourly && d.hourly.temperature_2m,
            })
            : null;
          const winEl = $('sideCondWindow');
          if (winEl) winEl.innerHTML = window.DoloPawsWeatherWindow
            ? window.DoloPawsWeatherWindow.markup(win)
            : 'No route-length daylight recommendation is available. Check the official forecast and plan to finish well before dusk.';
        }
        const hasWater = Array.isArray(t.waterSources) && t.waterSources.length > 0;
        const waterEl = $('tdCondWater');
        if (waterEl) { waterEl.textContent = hasWater ? 'On route' : 'Carry own'; waterEl.style.color = hasWater ? '#BDEBD9' : '#FFE6A6'; }
        if (condCard) condCard.hidden = false;

        // ---- 6-day forecast card ----
        if (fcDays) {
          let heatDay = null;
          fcDays.innerHTML = d.daily.time.map((iso, i) => {
            const label = i === 0 ? 'Today' : new Date(iso).toLocaleDateString(undefined, { weekday: 'short' });
            const hi = Math.round(d.daily.temperature_2m_max[i]);
            const lo = Math.round(d.daily.temperature_2m_min[i]);
            const b = dayBadge(hi);
            if (b.t === 'Heat' && !heatDay) heatDay = i === 0 ? 'Today' : new Date(iso).toLocaleDateString(undefined, { weekday: 'long' });
            return `<div class="td2-fcday${i ? ' brd' : ''}">`
              + `<span class="d${i ? '' : ' now'}">${label}</span>`
              + `<span class="ic">${iconFor(d.daily.weathercode[i])}</span>`
              + `<span class="tp"><b class="num">${hi}°</b> <span class="lo">${lo}°</span></span>`
              + `<span class="bd"><span class="td2-badge" style="background:${b.bg};color:${b.fg};">${b.t}</span></span>`
              + `</div>`;
          }).join('');
          const noteEl = $('tdForecastNote');
          if (noteEl && heatDay) {
            noteEl.innerHTML = `<b style="color:#8A5A16">${heatDay}</b> is warm. Walk early and carry extra water.`;
            noteEl.hidden = false;
          }
        }
        if (fcCard) fcCard.hidden = false;
      })
      .catch(() => publishWeather({ status: 'unavailable', capturedAt: Date.now() }));
  })();
})();
;

// ---- trail-detail-ui.js ----
/**
 * trail-detail-ui.js — small UI glue for the redesigned (single-scroll,
 * Strava-style) trail detail page. Self-contained: it only reads state the
 * other modules already own and reflects it into the new markup. No data
 * layer of its own. Runs only on pages that use the `.td2` layout.
 *
 * Responsibilities:
 *   1. Hero "Start the hike" button proxies hike-mode.js's map button, and a
 *      live recording banner mirrors the hike state.
 *   2. "Active now" pill on the hazards card follows #trailFlagsList content.
 *   3. Relevant section headings are personalised with the active dog's name.
 */
(function () {
  'use strict';
  if (!document.querySelector('.td2')) return;

  // ---- 1. Hero Start-the-hike proxy + live banner -------------------------
  const heroBtn = document.getElementById('heroStartHike');
  const liveBanner = document.getElementById('td2LiveBanner');
  const mapBox = document.getElementById('trailMapBox');
  const hikeHome = heroBtn && heroBtn.parentElement;
  const hikeNext = heroBtn && heroBtn.nextSibling;

  function placeHikeAction() {
    if (!heroBtn || !hikeHome) return;
    if (heroBtn.parentElement !== hikeHome) {
      hikeHome.insertBefore(heroBtn, hikeNext);
    }
  }
  placeHikeAction();

  function recording() {
    return !!(mapBox && mapBox.classList.contains('hike-status-visible'));
  }

  // Live progress mirrored from hike-mode (elapsed clock + km walked), shown
  // in the banner and in the hero End button ("End · 12:34", per prototype).
  let hikeStartedAt = null;
  let elapsedTimer = null;
  function fmtElapsed() {
    if (!hikeStartedAt) return '0:00';
    const s = Math.max(0, Math.floor((Date.now() - hikeStartedAt) / 1000));
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
    return h ? h + ':' + String(m).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0')
             : m + ':' + String(s % 60).padStart(2, '0');
  }
  function tickElapsed() {
    const el = document.getElementById('tdLiveElapsed');
    if (el) el.textContent = fmtElapsed();
    if (heroBtn && heroBtn.classList.contains('recording')) {
      const t = heroBtn.querySelector('.hike-elapsed');
      if (t) t.textContent = fmtElapsed();
    }
  }
  window.addEventListener('dolopaws-hike-progress', function (e) {
    hikeStartedAt = (e.detail && e.detail.startedAt) || hikeStartedAt;
    const dist = document.getElementById('tdLiveDist');
    if (dist && e.detail && typeof e.detail.km === 'number') dist.textContent = e.detail.km.toFixed(1) + ' km';
    if (!elapsedTimer) elapsedTimer = setInterval(tickElapsed, 1000);
    tickElapsed();
  });

  function syncHike() {
    const mapBtn = document.getElementById('mapStartHikeBtn');
    const rec = recording();
    if (heroBtn) {
      const nextHidden = !mapBtn;
      if (heroBtn.hidden !== nextHidden) heroBtn.hidden = nextHidden;
      heroBtn.classList.toggle('recording', rec);
      // The map observer calls syncHike whenever hike mode changes. Replacing
      // identical markup on every callback creates
      // a self-triggering mutation loop that locks the page. Only rewrite the
      // button when its actual state changes.
      const nextState = rec ? 'recording' : 'idle';
      if (heroBtn.dataset.hikeUiState !== nextState) {
        heroBtn.dataset.hikeUiState = nextState;
        heroBtn.innerHTML = rec
          ? '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/></svg> End · <span class="hike-elapsed">' + fmtElapsed() + '</span>'
          : '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg> Start the hike';
      }
    }
    if (liveBanner) liveBanner.hidden = !rec;
    if (!rec && elapsedTimer) { clearInterval(elapsedTimer); elapsedTimer = null; hikeStartedAt = null; }
  }
  if (heroBtn) {
    heroBtn.addEventListener('click', function () {
      const mapBtn = document.getElementById('mapStartHikeBtn');
      if (mapBtn) mapBtn.click();
    });
  }
  if (mapBox) {
    // hike-mode.js injects #mapStartHikeBtn and toggles .hike-status-visible.
    new MutationObserver(syncHike).observe(mapBox, {
      attributes: true, attributeFilter: ['class'], childList: true, subtree: true,
    });
  }
  // Poll briefly until hike-mode has injected its button, then let the
  // observer take over.
  let tries = 0;
  const iv = setInterval(function () {
    syncHike();
    if (document.getElementById('mapStartHikeBtn') || ++tries > 40) clearInterval(iv);
  }, 250);
  syncHike();

  // ---- 2. "Active now" hazard pill + section counts ----------------------
  const flags = document.getElementById('trailFlagsList');
  const hazardCard = document.getElementById('td2Hazards');
  const photos = document.getElementById('trailPhotosList');
  const reviews = document.getElementById('trailReviewsList');

  // Count real items in a list (children that aren't the empty-state block).
  function itemCount(list) {
    if (!list) return 0;
    if (list.querySelector('.empty-state')) return 0;
    return list.children.length;
  }
  function setCount(id, n) {
    const el = document.getElementById(id);
    if (el) el.textContent = n > 0 ? ' · ' + n : '';
  }
  function syncHazards() {
    if (!flags) return;
    const n = itemCount(flags);
    if (hazardCard) hazardCard.classList.toggle('has-active', n > 0);
    setCount('td2HazardCount', n);
  }
  function syncCounts() {
    const pc = itemCount(photos);
    setCount('td2PhotoCount', pc);
    const rc = itemCount(reviews);
    setCount('td2ReviewCount', rc);
    const photoCard = document.getElementById('td2PhotosCard');
    const reviewCard = document.getElementById('td2ReviewsCard');
    if (photoCard) photoCard.classList.toggle('is-empty', pc === 0);
    if (reviewCard) reviewCard.classList.toggle('is-empty', rc === 0);
    // Average rating from the rendered review ratings (aria-label "X out of 5").
    const avgEl = document.getElementById('td2ReviewAvg');
    if (avgEl && reviews) {
      const rated = [].map.call(reviews.querySelectorAll('.community-review__rating[aria-label]'), function (r) {
        const m = (r.getAttribute('aria-label') || '').match(/([\d.]+)\s*out of\s*5/i);
        return m ? parseFloat(m[1]) : null;
      }).filter(function (v) { return v != null; });
      if (rated.length) {
        const avg = rated.reduce(function (a, b) { return a + b; }, 0) / rated.length;
        avgEl.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style="flex:none;"><path d="M12 2.5l2.9 6.1 6.6.8-4.9 4.5 1.3 6.6L12 18l-5.9 3.1 1.3-6.6L2.5 9.4l6.6-.8z"/></svg> ' + avg.toFixed(1);
        avgEl.hidden = false;
      } else { avgEl.hidden = true; }
    }
  }
  if (flags) { new MutationObserver(syncHazards).observe(flags, { childList: true, subtree: true }); syncHazards(); }
  if (photos) { new MutationObserver(syncCounts).observe(photos, { childList: true, subtree: true }); }
  if (reviews) { new MutationObserver(syncCounts).observe(reviews, { childList: true, subtree: true }); }
  syncCounts();

  // ---- 3. Personalise section headers with the dog's name ----------------
  // (The sidebar dog card with its own match % is gone — the hero already
  // shows "N% match for <dog>", so repeating it below was redundant.)
  function syncDog() {
    let name = '';
    try {
      const s = JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null');
      if (s && s.hasProfile) name = s.name || '';
    } catch (e) { /* private mode — no summary */ }

    const safetyDog = document.getElementById('td2SafetyDog');
    if (safetyDog) safetyDog.textContent = name ? ' · ' + name : '';
    const nearbyTitle = document.getElementById('nearbyTitle');
    if (nearbyTitle && name) nearbyTitle.textContent = 'Nearby trails, ranked for ' + name;
    const liveTitle = document.getElementById('tdLiveTitle');
    if (liveTitle && name) liveTitle.textContent = 'Recording ' + name + '’s walk';
  }
  window.addEventListener('dolopaws-auth-changed', syncDog);
  syncDog();
})();
;

// ---- trail-mobile.js ----
/* Mobile app layout for the logged-in trail detail (≤700px) — ported from
   the Claude Design prototype "ORMA Trail Detail (Logged in) - Mobile".

   Same pattern as homepage-mobile.js: purely additive chrome on top of the
   desktop .td2 layout. Injects a compact top bar (back · brand · dog
   avatar) and a scroll progress bar. The complete set of
   real trail actions stays in the hero, so mobile has the same capabilities
   as desktop without mirrored handlers. All visual re-layout lives in
   trail-mobile.css under
   body.mtrail-active. Activates only for signed-in visitors (the same
   dolopaws-profile-summary signal trail-detail-ui.js already uses); guests
   keep the plain responsive page. */
(function(){
  'use strict';

  var page = document.querySelector('.td2');
  if(!page) return;

  var mq = window.matchMedia('(max-width:700px)');
  var active = false;
  var weather = document.querySelector('.td2-hero-weather');
  var weatherHome = weather && weather.parentElement;
  var weatherNext = weather && weather.nextSibling;
  var about = document.getElementById('td2AboutCard');
  var aboutHome = about && about.parentElement;
  var aboutNext = about && about.nextSibling;
  var offlinePanel = document.getElementById('offlinePackagePanel');
  var offlineHome = offlinePanel && offlinePanel.parentElement;
  var offlineNext = offlinePanel && offlinePanel.nextSibling;

  function placeWeather(){
    var slot = document.getElementById('mobileWeatherSlot');
    if(!weather || !weatherHome || !slot) return;
    if(mq.matches && weather.parentElement !== slot) slot.appendChild(weather);
    if(!mq.matches && weather.parentElement !== weatherHome){
      weatherHome.insertBefore(weather, weatherNext);
    }
  }

  function placeDownloadAction(){
    var row = document.querySelector('.td2-actrow');
    if(!offlinePanel || !offlineHome || !row) return;
    if(mq.matches && offlinePanel.parentElement !== row){
      row.insertBefore(offlinePanel, row.firstChild);
    }
    if(!mq.matches && offlinePanel.parentElement !== offlineHome){
      offlineHome.insertBefore(offlinePanel, offlineNext);
    }
  }

  function placeAboutAfterRecommendation(){
    var recommendation = document.getElementById('recommendationDecision');
    if(!about || !aboutHome || !recommendation || !recommendation.parentElement) return;
    if(about.previousElementSibling !== recommendation){
      recommendation.insertAdjacentElement('afterend', about);
    }
  }

  function restoreAbout(){
    if(!about || !aboutHome || about.parentElement === aboutHome) return;
    if(aboutNext && aboutNext.parentElement === aboutHome) aboutHome.insertBefore(about, aboutNext);
    else aboutHome.appendChild(about);
  }

  function initMobileDisclosures(){
    document.querySelectorAll('.td2-mobile-card-toggle').forEach(function(button){
      if(button.dataset.mobileDisclosureReady === 'true') return;
      button.dataset.mobileDisclosureReady = 'true';
      button.addEventListener('click', function(){
        var card = button.closest('.td2-mobile-collapsible');
        if(!card) return;
        var collapsed = card.classList.toggle('is-mobile-collapsed');
        button.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        var action = button.querySelector('.td2-mobile-toggle-action');
        if(action) action.innerHTML = (collapsed ? 'Show <span aria-hidden="true">⌄</span>' : 'Hide <span aria-hidden="true">⌃</span>');
      });
    });
  }

  function profileSummary(){
    try { return JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null'); }
    catch(e){ return null; }
  }
  function signedIn(){
    if(window.DoloPawsAuth && window.DoloPawsAuth.currentUser) return true;
    // Same dev-preview contract as the homepage (?view=returning).
    try { if(new URLSearchParams(window.location.search).get('view') === 'returning') return true; } catch(e){}
    var s = profileSummary();
    return !!(s && s.hasProfile);
  }

  function dogAvatarHtml(){
    var s = profileSummary();
    var active = s && Array.isArray(s.dogs)
      ? (s.dogs.find(function(dog){ return dog.id === s.activeDogId; }) || s.dogs[0])
      : null;
    var name = active && active.name ? String(active.name) : (s && s.name ? String(s.name) : '');
    var photo = active && typeof active.photo === 'string' && active.photo.indexOf('data:image/') === 0
      ? active.photo : null;
    if(photo) return '<span class="av" style="background-image:url(' + photo + ')" aria-hidden="true"></span>';
    return '<span class="av" aria-hidden="true">' + (name ? name.charAt(0).toUpperCase() : '🐾') + '</span>';
  }

  function ensureUi(){
    if(!document.getElementById('mtrailTop')){
      var top = document.createElement('div');
      top.className = 'mtrail-top';
      top.id = 'mtrailTop';
      top.innerHTML =
        '<a class="back" href="browse-trails.html">← <span>Trails</span></a>' +
        '<a class="brand" href="/"><img src="logo.svg" alt="">ORMA</a>' +
        '<a class="avlink" href="account.html" aria-label="Your account">' + dogAvatarHtml() + '</a>' +
        '<div class="mtrail-progress" aria-hidden="true"><span id="mtrailProgress"></span></div>';
      document.body.insertBefore(top, document.body.firstChild);
    }
  }

  function measure(){
    var top = document.getElementById('mtrailTop');
    if(top) document.body.style.setProperty('--mtrail-top', top.offsetHeight + 'px');
  }

  function onScroll(){
    if(!active) return;
    var fill = document.getElementById('mtrailProgress');
    if(!fill) return;
    var doc = document.documentElement;
    var max = (doc.scrollHeight - window.innerHeight) || 1;
    var pct = Math.max(0, Math.min(1, (window.scrollY || doc.scrollTop || 0) / max));
    fill.style.width = (pct * 100).toFixed(1) + '%';
  }

  function activate(){
    if(active) return;
    active = true;
    ensureUi();
    placeAboutAfterRecommendation();
    document.body.classList.add('mtrail-active');
    measure();
    setTimeout(function(){ if(active){ measure(); onScroll(); } }, 120);
  }

  function deactivate(){
    if(!active) return;
    active = false;
    restoreAbout();
    document.body.classList.remove('mtrail-active');
    document.body.style.removeProperty('--mtrail-top');
  }

  function update(){
    initMobileDisclosures();
    placeWeather();
    placeDownloadAction();
    if(mq.matches && signedIn()) activate();
    else deactivate();
  }

  if(mq.addEventListener) mq.addEventListener('change', update);
  else if(mq.addListener) mq.addListener(update);
  window.addEventListener('dolopaws-auth-changed', function(){ setTimeout(update, 0); });
  window.addEventListener('resize', function(){ update(); if(active) measure(); });
  window.addEventListener('scroll', onScroll, { passive: true });

  update();
})();
;

// ---- recommendation-decision.js ----
(function(root, factory){
  const api = factory();
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.DoloPawsRecommendationDecision = api;
})(typeof window !== 'undefined' ? window : globalThis, function(){
  'use strict';

  const CATEGORY = Object.freeze({
    'strong-option': { label:'Strong option', tone:'strong' },
    'possible-with-cautions': { label:'Possible with cautions', tone:'caution' },
    'not-recommended': { label:'Not recommended', tone:'stop' },
  });

  function translatedMessage(item, translate){
    if(!(item && item.message)) return '';
    if(typeof translate !== 'function') return item.message;
    const key = `recommendation.reason.${item.messageKey || item.code}`;
    const value = translate(key, item.vars || undefined);
    return value && value !== key ? value : item.message;
  }

  function messages(items, translate){
    return (Array.isArray(items) ? items : [])
      .map(item => translatedMessage(item, translate))
      .filter(Boolean);
  }

  // Calm framing: confidence describes data completeness, not danger.
  // "low" must not read as a warning — missing data never lowers the score.
  const CONFIDENCE_LABEL = Object.freeze({
    high: 'Based on detailed trail data',
    medium: 'Based on available trail data',
    low: 'Based on partial data',
  });

  function present(recommendation, context){
    recommendation = recommendation || {};
    context = context || {};
    const category = CATEGORY[recommendation.category] || {
      label:'Recommendation unavailable',
      tone:'unknown',
    };
    const translate = context.translate;
    const tr = (key, fallback, vars) => {
      if(typeof translate === 'function'){
        const value = translate(key, vars);
        if(value && value !== key) return value;
      }
      let output = fallback;
      for(const name of Object.keys(vars || {})){
        output = output.split(`{${name}}`).join(vars[name]);
      }
      return output;
    };
    const reasons = messages(recommendation.positiveReasons, translate);
    const cautions = messages(recommendation.hardStops, translate)
      .concat(messages(recommendation.cautions, translate));
    const rawUnknowns = (Array.isArray(recommendation.unknowns) ? recommendation.unknowns : [])
      .filter(Boolean);
    const unknowns = messages(rawUnknowns, translate);
    // The unknown codes encode their owner: dog.* gaps are fixable by the
    // user right now (profile fields); everything else is trail data.
    const dogGapFields = rawUnknowns
      .filter(item => typeof item.code === 'string' && item.code.startsWith('dog.'))
      .map(item => item.code.split('.')[1])
      .filter(Boolean);
    const dogName = String(context.dogName || '').trim();

    return {
      confidenceLabel:recommendation.confidence && CONFIDENCE_LABEL[recommendation.confidence]
        ? tr(`recommendation.confidence.${recommendation.confidence}`, CONFIDENCE_LABEL[recommendation.confidence])
        : null,
      dogGapFields,
      trailUnknownCount:rawUnknowns.length - dogGapFields.length,
      conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
      tone:category.tone,
      score:Number.isFinite(recommendation.score) ? recommendation.score : null,
      confidence:recommendation.confidence || 'unknown',
      scoringVersion:recommendation.scoringVersion || 'unknown',
      evidenceTier:recommendation.evidenceTier || 'unknown',
      contextLabel:dogName
        ? tr('recommendation.context.dog', 'Recommendation for {name}', { name:dogName })
        : tr('recommendation.context.guest', 'Unpersonalized planning view'),
      dogName:dogName || null,
      reasons:reasons.slice(0, 4),
      cautions:cautions.slice(0, 4),
      unknowns:unknowns.slice(0, 5),
      additionalUnknowns:Math.max(0, unknowns.length - 5),
      heroSummary:dogName
        ? tr('recommendation.hero.dog', '{conclusion} for {name}.', {
          conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
          name:dogName,
        })
        : tr('recommendation.hero.guest', '{conclusion} in an unpersonalized planning view.', {
          conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
        }),
    };
  }

  return Object.freeze({ CATEGORY, present, translatedMessage });
});
;

// ---- recommendation-guides.js ----
(function(root, factory){
  const api = factory();
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.DoloPawsRecommendationGuides = api;
})(typeof window !== 'undefined' ? window : globalThis, function(){
  'use strict';

  const GUIDES = Object.freeze({
    heat:Object.freeze({
      id:'heat',
      href:'guides/heat-overheating.html',
      label:'Recognising overheating early',
      summary:'Know the early signs and when to stop.',
    }),
    water:Object.freeze({
      id:'water',
      href:'guides/water-for-dogs-on-trail.html',
      label:'Water for dogs on alpine trails',
      summary:'Plan the full supply when reliable water is not confirmed.',
    }),
    paws:Object.freeze({
      id:'paws',
      href:'guides/paw-protection.html',
      label:'Protecting paw pads on rocky terrain',
      summary:'Prepare for rough surfaces and recognise pad damage.',
    }),
    exposure:Object.freeze({
      id:'exposure',
      href:'safety-guide.html',
      label:'Dog hiking safety guide',
      summary:'Review turn-back decisions and emergency preparation.',
    }),
    livestock:Object.freeze({
      id:'livestock',
      href:'guides/livestock-guard-dogs.html',
      label:'Livestock and guardian dogs',
      summary:'Cross grazed pasture calmly and avoid confrontations.',
    }),
    altitude:Object.freeze({
      id:'altitude',
      href:'guides/altitude-with-your-dog.html',
      label:'Hiking safely at altitude',
      summary:'Plan for thinner air, rapid weather changes and lingering snow.',
    }),
  });

  function guideId(code){
    code = String(code || '');
    if(/^(?:trail\.(?:heat|shade)|conditions\.heat)\./.test(code)) return 'heat';
    if(/^trail\.water\./.test(code)) return 'water';
    if(/^trail\.(?:surface-hazards|terrain|descent)\./.test(code)) return 'paws';
    if(/^trail\.exposure\./.test(code)) return 'exposure';
    if(/^trail\.livestock\./.test(code)) return 'livestock';
    if(/^trail\.altitude\./.test(code)) return 'altitude';
    return null;
  }

  function select(recommendation, maximum){
    const candidates = []
      .concat(Array.isArray(recommendation && recommendation.hardStops)
        ? recommendation.hardStops : [])
      .concat(Array.isArray(recommendation && recommendation.cautions)
        ? recommendation.cautions : []);
    const selected = [];
    const seen = new Set();
    const cap = Number.isFinite(maximum) ? Math.max(0, maximum) : 2;
    for(const caution of candidates){
      const id = guideId(caution && caution.code);
      if(!id || seen.has(id)) continue;
      seen.add(id);
      selected.push(GUIDES[id]);
      if(selected.length >= cap) break;
    }
    return selected;
  }

  function selectIds(ids, maximum){
    const selected = [];
    const seen = new Set();
    const cap = Number.isFinite(maximum) ? Math.max(0, maximum) : 3;
    for(const id of Array.isArray(ids) ? ids : []){
      if(!GUIDES[id] || seen.has(id)) continue;
      seen.add(id);
      selected.push(GUIDES[id]);
      if(selected.length >= cap) break;
    }
    return selected;
  }

  return Object.freeze({ GUIDES, select, selectIds });
});
;

// ---- trail-recommendation.js ----
(function(){
  'use strict';

  function esc(value){
    return String(value == null ? '' : value).replace(/[&<>"']/g, char => ({
      '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;',
    })[char]);
  }

  function tr(key, fallback, vars){
    if(typeof window.t === 'function'){
      const value = window.t(key, vars);
      if(value && value !== key) return value;
    }
    let output = fallback;
    for(const name of Object.keys(vars || {})){
      output = output.split(`{${name}}`).join(vars[name]);
    }
    return output;
  }

  function list(items, emptyText){
    if(!items.length) return `<p class="recommendation-empty">${esc(emptyText)}</p>`;
    return `<ul>${items.map(item => `<li>${esc(item)}</li>`).join('')}</ul>`;
  }

  function renderGuideLinks(recommendation){
    const root = document.getElementById('trailGuideLinks');
    const api = window.DoloPawsRecommendationGuides;
    if(!root || !api){ return; }
    const safetyRows = document.getElementById('dogSafetyRows');
    if(!safetyRows) return;
    safetyRows.querySelectorAll('[data-guide-id]').forEach(row => {
      const guide = api.GUIDES[row.dataset.guideId];
      if(!guide || row.querySelector('.safety-row-guide')) return;
      const copy = row.querySelector('.safety-row-copy') || row;
      copy.insertAdjacentHTML('beforeend',
        `<a class="safety-row-guide" href="${esc(guide.href)}">${esc(tr(`recommendation.guide.${guide.id}.label`, guide.label))} <span aria-hidden="true">→</span></a>`
      );
    });
    root.hidden = true;
    root.innerHTML = '';
  }

  function currentTrail(){
    const id = new URLSearchParams(window.location.search).get('id');
    return typeof trails !== 'undefined' ? trails.find(trail => trail.id === id) : null;
  }

  function subjectFor(profile){
    if(!profile) return {};
    return typeof effectiveOverrides === 'function'
      ? effectiveOverrides(profile, null)
      : profile;
  }

  function renderDecision(trail, profile){
    const root = document.getElementById('recommendationDecision');
    const api = window.DoloPawsRecommendationDecision;
    if(!root || !api || typeof recommendTrail !== 'function') return;
    const recommendation = recommendTrail(trail, subjectFor(profile));
    const view = api.present(recommendation, {
      dogName:profile && profile.name,
      translate:window.t,
    });
    const score = view.score === null ? '' : `<span class="recommendation-score">${view.score}%</span>`;
    // Confidence rides next to the score as a calm data-completeness chip;
    // the audit trail (scoring version, trail-data gaps) lives in the
    // evidence disclosure, not on the card face.
    const chip = view.confidenceLabel
      ? `<span class="recommendation-confidence recommendation-confidence--${esc(view.confidence)}">${esc(view.confidenceLabel)}</span>`
      : '';
    // Dog-side gaps are the one thing the reader can fix right now — the
    // card face turns them into a profile CTA instead of a caveat.
    const gapCta = !view.dogName
      ? `<p class="recommendation-gaps"><a href="onboarding.html">${esc(tr('recommendation.gap.addDog', 'Add your dog to sharpen this score →'))}</a></p>`
      : view.dogGapFields.length
        ? `<p class="recommendation-gaps"><a href="account.html">${esc(tr('recommendation.gap.fields', 'Add {name}’s {fields} to sharpen this score →', {
            name:view.dogName,
            fields:friendlyList(view.dogGapFields),
          }))}</a></p>`
        : '';

    root.className = `recommendation-decision recommendation-decision--${view.tone}`;
    root.dataset.scoringVersion = view.scoringVersion;
    root.dataset.recommendationCategory = recommendation.category || '';
    root.dataset.recommendationConfidence = view.confidence;
    root.innerHTML =
      '<div class="recommendation-head">' +
        '<div>' +
          `<div class="recommendation-kicker">${esc(view.contextLabel)}</div>` +
          `<h2>${esc(view.conclusion)} ${score} ${chip}</h2>` +
          gapCta +
        '</div>' +
      '</div>' +
      '<div class="recommendation-columns">' +
        `<section><h3>${esc(tr('recommendation.reasons.title', 'Why it may fit'))}</h3>` +
          list(view.reasons, tr('recommendation.reasons.empty', 'No positive reason is established yet.')) + '</section>' +
        `<section><h3>${esc(tr('recommendation.cautions.title', 'Cautions'))}</h3>` +
          list(view.cautions, tr('recommendation.cautions.empty', 'No specific caution is identified; review unknowns before deciding.')) + '</section>' +
      '</div>' +
      '<div class="recommendation-actions" aria-label="Trail actions">' +
        `<button type="button" data-recommendation-save>${esc(tr('recommendation.action.save', 'Save trail'))}</button>` +
        `<button type="button" data-recommendation-compare>${esc(tr('recommendation.action.compare', 'Add to comparison'))}</button>` +
        `<button type="button" data-recommendation-download disabled>${esc(tr('recommendation.action.offlineUnavailable', 'Offline map unavailable'))}</button>` +
      '</div>';
    root.hidden = false;

    renderGuideLinks(recommendation);
    const hero = document.getElementById('heroVerdict');
    if(hero) hero.textContent = view.heroSummary;
    wireActions(root, trail);
  }

  function friendlyList(items){
    const labels = items.map(item => tr(
      `recommendation.profileField.${item}`,
      item
    ));
    if(labels.length <= 1) return labels.join('');
    return tr('recommendation.list.and', '{first} and {last}', {
      first:labels.slice(0, -1).join(', '),
      last:labels[labels.length - 1],
    });
  }

  function wireActions(root, trail){
    const save = root.querySelector('[data-recommendation-save]');
    const originalSave = document.getElementById('detailSaveBtn');
    const syncSave = () => {
      save.textContent = originalSave && originalSave.classList.contains('saved')
        ? tr('recommendation.action.saved', 'Saved')
        : tr('recommendation.action.save', 'Save trail');
      save.setAttribute('aria-pressed', String(!!(
        originalSave && originalSave.classList.contains('saved')
      )));
    };
    save.disabled = !originalSave;
    if(originalSave){
      syncSave();
      save.addEventListener('click', () => originalSave.click());
      new MutationObserver(syncSave).observe(originalSave, {
        attributes:true,
        childList:true,
        subtree:true,
      });
    }

    const compare = root.querySelector('[data-recommendation-compare]');
    const comparison = window.DoloPawsComparisonState;
    if(comparison){
      const available = trails.map(item => item.id);
      const selected = comparison.load(localStorage, available);
      const alreadySelected = selected.includes(trail.id);
      compare.textContent = alreadySelected
        ? tr('recommendation.action.openComparison', 'Open comparison')
        : tr('recommendation.action.compare', 'Add to comparison');
      compare.addEventListener('click', () => {
        let ids = comparison.load(localStorage, available);
        if(!ids.includes(trail.id)) ids = comparison.toggle(ids, trail.id);
        comparison.save(localStorage, ids);
        window.location.href = ids.length >= 2
          ? comparison.compareHref(ids)
          : 'browse-trails.html';
      });
    }else{
      compare.disabled = true;
    }

    const download = root.querySelector('[data-recommendation-download]');
    const originalDownload = document.getElementById('offlineDownloadBtn');
    const offlinePanel = document.getElementById('offlinePackagePanel');
    const enableDownload = () => {
      if(!offlinePanel || offlinePanel.hidden) return;
      download.disabled = false;
      download.textContent = tr('recommendation.action.download', 'Download offline map');
    };
    if(window.DoloPawsOffline && originalDownload){
      if(offlinePanel){
        enableDownload();
        new MutationObserver(enableDownload).observe(offlinePanel, { attributes:true });
      }
      window.DoloPawsOffline.availablePackage(trail.id).then(manifest => {
        if(!manifest) return;
        enableDownload();
      }).catch(() => {});
      download.addEventListener('click', () => {
        if(!download.disabled) originalDownload.click();
      });
    }
  }

  async function renderCurrent(){
    const trail = currentTrail();
    if(!trail) return;
    let profile = null;
    if(window.DoloPawsAuth && window.DoloPawsAuth.currentUser){
      try { profile = await window.DoloPawsAuth.getDogProfile(); } catch(error){}
    }
    renderDecision(trail, profile);
  }

  renderCurrent();
  if(!window.DoloPawsAuthReady){
    window.addEventListener('dolopaws-auth-ready', renderCurrent, { once:true });
  }
  window.addEventListener('dolopaws-auth-changed', renderCurrent);
})();
;
